INSERT INTO notes (id, source, title, heading, body, words, seeded_at) VALUES
  ('L1.1', 'docs/lessons/week-01.md', 'Lesson 1 — What Is a Market? (and why we grade process, not outcomes)', 'Overview', '90 minutes · Phase 1, week 1 · Toolkit feature: the live site + `GET /api/hello`', 16, '2026-11-12T13:40:44.802Z'),
  ('L1.2', 'docs/lessons/week-01.md', 'Lesson 1 — What Is a Market? (and why we grade process, not outcomes)', 'By the end, students can', '1. Explain in their own words what a share is, what an exchange does, and where a price comes from.
2. Tell the difference between a good decision and a good outcome — and name "resulting" when they see it.
3. Complete their first decision-journal entry (on an everyday decision, not a trade).', 53, '2026-11-12T13:40:44.802Z'),
  ('L1.3', 'docs/lessons/week-01.md', 'Lesson 1 — What Is a Market? (and why we grade process, not outcomes)', '0:00 — Welcome and the promise', 'Who you are, why this course exists. Make the three promises out loud and write them up: paper portfolios only; no tips, ever; everything we build is open. Then the sentence the whole course hangs on: "In this room we grade decisions, not outcomes." Tell them it won''t make sense yet; it will by 8pm.', 55, '2026-11-12T13:40:44.802Z'),
  ('L1.4', 'docs/lessons/week-01.md', 'Lesson 1 — What Is a Market? (and why we grade process, not outcomes)', '0:10 — What is a share? What is an exchange?', 'Cocktail-napkin level, no jargon wall: a share is a slice of a real business; you''re buying it from another person, not from the company (secondary market); an exchange is just the room — now a computer — where buyers and sellers find each other; a price is nothing more than the last deal two strangers agreed to. Take questions but park anything about "which shares are good" — visibly, on a "Parked" list. It builds trust that parked things return.', 80, '2026-11-12T13:40:44.802Z'),
  ('L1.5', 'docs/lessons/week-01.md', 'Lesson 1 — What Is a Market? (and why we grade process, not outcomes)', '0:25 — The sweet auction', 'Auction the three chocolate bars one at a time, open outcry, paid in the small sweets you dealt out unevenly on purpose. Record each hammer price on the flip chart. Then the debrief, which is the actual lesson: the bars were identical — why did the prices differ? Draw out: who had more sweets (budget), who wanted it more (sentiment), who saw others bidding (momentum!), how the last price became "the price" in everyone''s head. You have just taught price formation, order flow, and anchoring without naming any of them. Name them now, lightly.', 94, '2026-11-12T13:40:44.802Z'),
  ('L1.6', 'docs/lessons/week-01.md', 'Lesson 1 — What Is a Market? (and why we grade process, not outcomes)', '0:40 — Luck vs skill: the coin-flip champion', 'Everyone stands. Each round, call heads or tails before the flip; wrong guesses sit. Crown the last person standing "the room''s best coin predictor" and let that sit for a beat — then ask if anyone would pay them for coin tips. Introduce resulting: judging a decision by its outcome. A good outcome from a bad process is luck; you cannot rerun life, so we grade the part we control. Real-world hook: ask for a show of hands who knows someone who "made a killing" on some share or coin — was that skill? How would we ever know? (Answer: process, written down, in advance.)', 105, '2026-11-12T13:40:44.802Z'),
  ('L1.7', 'docs/lessons/week-01.md', 'Lesson 1 — What Is a Market? (and why we grade process, not outcomes)', '0:55 — The decision journal', 'Hand out the template and walk it field by field. Then everyone completes a practice entry on an everyday decision with genuine uncertainty — the route home tonight, whether to fix or float the mortgage, whether to buy the bigger bag of coal. The point: thesis before, review after, rules in between. Every paper trade in this course requires an entry before execution — no entry, no trade. That rule is never waived.', 73, '2026-11-12T13:40:44.802Z'),
  ('L1.8', 'docs/lessons/week-01.md', 'Lesson 1 — What Is a Market? (and why we grade process, not outcomes)', '1:10 — The toolkit reveal', 'Phones out; everyone opens the site. Walk the twelve-week ledger on screen: week 1 is stamped shipped, eleven rows to go. Then the punchline — tap `GET /api/hello` and show them the entire toolkit today is one page and one route. It grows a capability a week, in public, and they can watch the source code the whole way. This is deliberate: the course trusts them with how the sausage is made, because opacity is where the fee-takers and the scammers live. (First scam-literacy seed, planted lightly — it flowers in weeks 6 and 11.)', 95, '2026-11-12T13:40:44.802Z');
INSERT INTO notes (id, source, title, heading, body, words, seeded_at) VALUES
  ('L1.9', 'docs/lessons/week-01.md', 'Lesson 1 — What Is a Market? (and why we grade process, not outcomes)', '1:25 — Homework and close', 'Two items: (1) bring one financial headline or social-media post that smells like luck dressed up as skill — we''ll open week 2 with the best ones; (2) keep the journal template somewhere they''ll see it. Close by repeating the sentence: decisions, not outcomes.', 44, '2026-11-12T13:40:44.802Z'),
  ('L2.1', 'docs/lessons/week-02.md', 'Lesson 2 — Where Prices Come From (and what "free" really costs)', 'Overview', '90 minutes · Phase 1, week 2 · Toolkit feature: `GET /api/quote/:ticker` + the lookup form', 16, '2026-11-12T13:40:44.802Z'),
  ('L2.2', 'docs/lessons/week-02.md', 'Lesson 2 — Where Prices Come From (and what "free" really costs)', 'By the end, students can', '1. Read a quote screen: last price, bid, ask, spread, volume, OHLC, previous close.
2. Explain why our course data is delayed and rationed — and why that itself is a price signal about the value of data.
3. Explain what a split or dividend does to a price chart, and why "adjusted" prices exist.', 55, '2026-11-12T13:40:44.802Z'),
  ('L2.3', 'docs/lessons/week-02.md', 'Lesson 2 — Where Prices Come From (and what "free" really costs)', '0:00 — Homework harvest: the Wall of Resulting', 'Headlines out. Each contributor gets one sentence on why theirs smells like luck dressed as skill. Class votes; the winner gets pinned up and stays up all term — the Wall of Resulting grows weekly. (Recurring bit, low prep, compounds nicely.)', 41, '2026-11-12T13:40:44.802Z'),
  ('L2.4', 'docs/lessons/week-02.md', 'Lesson 2 — Where Prices Come From (and what "free" really costs)', '0:10 — What a quote actually is', 'Build on week 1''s "a price is the last deal two strangers agreed": the last price is history; the bid and ask are the two queues of people waiting to deal, and the spread between them is a toll bridge you pay to cross in a hurry. Volume is how busy the bridge is. OHLC is a whole day compressed to four numbers. Activity: hand out the two printed quote screens — find the spread on each, then compute the cost of buying and immediately selling €1,000 worth. That number goes on the flip chart as the first entry in the course''s running cost ledger. The small-cap''s toll will genuinely surprise them.', 112, '2026-11-12T13:40:44.802Z'),
  ('L2.5', 'docs/lessons/week-02.md', 'Lesson 2 — Where Prices Come From (and what "free" really costs)', '0:25 — Why is our data delayed?', 'Because immediacy is the product. Exchanges sell speed: co-located real-time feeds for serious money, 15-minute-delayed for cheap seats, end-of-day for free. Our course sits at the free end by design — nothing this course teaches needs speed, and (plant this flag now) feeling that you need speed is usually a sign you''re gambling, not investing.', 55, '2026-11-12T13:40:44.802Z'),
  ('L2.6', 'docs/lessons/week-02.md', 'Lesson 2 — Where Prices Come From (and what "free" really costs)', '0:35 — The ration book', 'Point at the 25 on the board. That''s the entire class allowance of live lookups per day on the free data tier; the second provider allows about 250. Discussion: if you had 25 looks a day at the whole market, how would you spend them? Let it run a few minutes — someone will say some version of "why doesn''t it just fetch everything once at night and remember it?" That student has just invented week 3. Name it, credit them, promise it. (If nobody says it, ask: "what would a sensible person do instead of looking things up one at a time?")', 103, '2026-11-12T13:40:44.802Z'),
  ('L2.7', 'docs/lessons/week-02.md', 'Lesson 2 — Where Prices Come From (and what "free" really costs)', '0:45 — Splits and dividends, or: why charts lie', 'Flip chart: a €100 share does a 2-for-1 split → two €50 shares. The chart shows a 50% "crash" in which nobody lost a cent. Same trick in miniature every time a dividend is paid — the cash leaks out of the price on the ex-date. Hence adjusted prices: history restated as if today''s share structure had always existed. Rule of thumb for the course: raw prices for what happened today, adjusted prices for any chart longer than a season. Week 3''s nightly history will store adjusted closes for exactly this reason.', 92, '2026-11-12T13:40:44.802Z');
INSERT INTO notes (id, source, title, heading, body, words, seeded_at) VALUES
  ('L2.8', 'docs/lessons/week-02.md', 'Lesson 2 — Where Prices Come From (and what "free" really costs)', '0:55 — Toolkit time: spend the ration deliberately', 'Phones out. Budget ~8 of the 25, spent as an experiment plan, not a scramble:
1. `AAPL` — a liquid US mega-cap; read the JSON fields aloud together.
2. `TSCO.LON` — a UK listing; note the symbol dialect differs by provider.
3. One student-chosen ticker.
4. A nonsense ticker — watch the toolkit fail politely and explain itself. Failing well is a feature; scams never fail well.
5. If the class is lively and the budget dies early — celebrate. Reading the rate-limit message live off the screen is the entire lesson in one JSON field.
Point out two honest details in every response: `"delayed": true`, and the `warnings` array. The toolkit tells the truth about its own data. That''s the standard everything they meet after this course should be held to.', 132, '2026-11-12T13:40:44.802Z'),
  ('L2.9', 'docs/lessons/week-02.md', 'Lesson 2 — Where Prices Come From (and what "free" really costs)', '1:15 — The transparency minute', 'On screen: `.dev.vars.example` next to `.gitignore` in the public repo. The lock and the promise, side by side: the code is open, the keys are not, and they can verify both claims themselves. (Scam-literacy seed #2: real systems show you how they work and how they protect secrets.)', 48, '2026-11-12T13:40:44.802Z'),
  ('L2.10', 'docs/lessons/week-02.md', 'Lesson 2 — Where Prices Come From (and what "free" really costs)', '1:20 — Close + homework', 'Repeat the sentence. Homework: pick one company you genuinely encounter in daily life — the shop, the phone, the airline — and write a journal entry titled "What do I actually know about this business?" No numbers, no looking anything up; just knowledge from living. (This feeds week 4 directly.) Second, smaller: use the lookup to find your company''s ticker — and if the lookup can''t find it, write that down too. Coverage gaps are data.', 76, '2026-11-12T13:40:44.802Z'),
  ('L3.1', 'docs/lessons/week-03.md', 'Lesson 3 — The Nightly Close (and the student who invented it)', 'Overview', '90 minutes · Phase 1, week 3 · Toolkit feature: nightly cron → cache, `/prices/:ticker` charts, `/api/universe`', 17, '2026-11-12T13:40:44.802Z'),
  ('L3.2', 'docs/lessons/week-03.md', 'Lesson 3 — The Nightly Close (and the student who invented it)', 'By the end, students can', '1. Say what "the close" is, when it happens on an Irish clock, and why one calm number a day beats a flickering feed.
2. Read a daily price chart: trend, range, and the difference between a wiggle and a move.
3. Explain what the course universe is, why it''s a verified list, and why some famous names aren''t in it.', 61, '2026-11-12T13:40:44.802Z'),
  ('L3.3', 'docs/lessons/week-03.md', 'Lesson 3 — The Nightly Close (and the student who invented it)', '0:00 — Wall of Resulting + homework harvest', 'New headline nominations, one-sentence pitches, vote, pin. Then the week-2 homework: who couldn''t find their company in the lookup? Collect the misses on the flip chart — titled "Coverage gaps are data." Keep the list; it pays off at 0:40.', 40, '2026-11-12T13:40:44.802Z'),
  ('L3.4', 'docs/lessons/week-03.md', 'Lesson 3 — The Nightly Close (and the student who invented it)', '0:10 — What is "the close"?', 'New York trades 2:30pm–9:00pm our time. The close is the last agreed deal of the day — the number the whole world writes down. Draw the day as a squiggle on the flip chart, then circle one point: everything else evaporates; this survives. Indices in one breath (S&P 500 = a basket''s close). Then the course''s stance, said plainly: we look once a day, after the noise stops, because calm decisions come from calm data — and anyone selling you urgency is selling something.
0:15 of this block — deliver the invention. Remind the room who said, in week 2, "why not fetch everything once at night and remember it?" Name them. Tonight at 11:30pm Irish time, a robot does exactly their idea: visits every company on our list, writes down the close, goes back to sleep. Their idea, running nightly, in public.', 143, '2026-11-12T13:40:44.802Z'),
  ('L3.5', 'docs/lessons/week-03.md', 'Lesson 3 — The Nightly Close (and the student who invented it)', '0:25 — Reading a chart without fooling yourself', 'Project `/prices/AAPL`. Walk it: the line is adjusted closes (week 2''s splits lesson — this is why the chart doesn''t "crash" on a split); the labels are max, min, last; the range links switch 3 months ↔ 5 years. The honest exercise: show 3 months, ask "trend?" — then show 5 years and ask again. Same company, same data, different story. The timeframe is a choice someone makes before showing you a chart. That sentence is scam-literacy seed #3.', 79, '2026-11-12T13:40:44.802Z');
INSERT INTO notes (id, source, title, heading, body, words, seeded_at) VALUES
  ('L3.6', 'docs/lessons/week-03.md', 'Lesson 3 — The Nightly Close (and the student who invented it)', '0:40 — The universe, and why it''s small', 'Open `/api/universe` on screen. This is the tin, and you can read the label: every company we track, how many days of history, when it was last refreshed. Then the honest bit — connect to the 0:00 gap list: the free data plan doesn''t cover everything; some companies we wanted (including nearly every Dublin-listed Irish name) aren''t served. So the course universe is a verified list — every name on it was tested, and the test results are published in the repo. Nobody hid the gaps; we documented them. Contrast that with any tip-seller''s stock list, where you never see what was left out or why. (Tutor honesty, if asked "so is Irish data rubbish?": no — Irish companies'' own champions mostly moved their main listings to New York; our data follows where the trading went. Week 11 shows the same migration in the fee schedule.)', 146, '2026-11-12T13:40:44.802Z'),
  ('L3.7', 'docs/lessons/week-03.md', 'Lesson 3 — The Nightly Close (and the student who invented it)', '0:55 — Toolkit time: chart safari', 'Phones out, no budget, no queue — the cache is theirs to hammer. Each student: (1) chart their week-2 company if it''s in the universe, else adopt one from `/api/universe`; (2) find its best and worst stretch over 5 years; (3) one journal line: "What story does the shape suggest — and what does the shape NOT tell me?" (It can''t tell you why; it can''t tell you next.) Circulate; collect one surprise per table at the end. Point out the milliseconds line under each chart — last week one lookup took most of a second and cost ration; tonight it''s instant and free, because we stopped asking the world and started asking our own notebook.', 116, '2026-11-12T13:40:44.802Z'),
  ('L3.8', 'docs/lessons/week-03.md', 'Lesson 3 — The Nightly Close (and the student who invented it)', '1:15 — The robot''s diary', 'Show the `last_nightly_run` line in `/api/universe` metadata. The robot keeps a log of every visit — successes, failures, refusals — and the log is public. A system that records its own failures is a system you can begin to trust. (This is also your segue to how banks and brokers are audited — and to week 6''s "scams never fail well.")', 61, '2026-11-12T13:40:44.802Z'),
  ('L3.9', 'docs/lessons/week-03.md', 'Lesson 3 — The Nightly Close (and the student who invented it)', '1:20 — Close + homework', 'Homework: (1) each night this week, glance at your company''s chart — without acting on anything; notice the urge, journal it once ("day 3: wanted to do something; didn''t; nothing was lost"); (2) bring one question about what makes a company worth something — week 4 opens the books.', 49, '2026-11-12T13:40:44.802Z'),
  ('L4.1', 'docs/lessons/week-04.md', 'Lesson 4 — What Is a Company Worth? (Mr. Market moves into your phone)', 'Overview', '90 minutes · Phase 2, week 1 of 3 · Toolkit feature: the books page — `/fundamentals/:ticker`
Phase 2 methodology note: Benjamin Graham throughout — the readable half from The Intelligent Investor (your 2003 Revised Edition, Zweig commentary), the reasoning underneath from Security Analysis (1940 second edition). Alternatives get named only so students can recognise them.', 56, '2026-11-12T13:40:44.802Z'),
  ('L4.2', 'docs/lessons/week-04.md', 'Lesson 4 — What Is a Company Worth? (Mr. Market moves into your phone)', 'By the end, students can', '1. Name the two statements the toolkit reads — what a company owns and owes (balance sheet) and what it earned (income statement) — and find four lines on each.
2. Say what EPS, book value, current ratio and long-term debt each measure, in kitchen-table words.
3. Retell the Mr. Market parable — and recognise him in a trading app''s push notification.
4. Open their homework company''s books on the course site and read five years in one screen.', 79, '2026-11-12T13:40:44.802Z'),
  ('L4.3', 'docs/lessons/week-04.md', 'Lesson 4 — What Is a Company Worth? (Mr. Market moves into your phone)', '0:00 — Wall of Resulting + harvest', 'New nominations, vote, pin. Then collect last week''s discipline-drill journals in one round: who felt the urge to act on a nightly glance? What did doing nothing cost? (Usually: nothing. That''s the point landing.)', 34, '2026-11-12T13:40:44.802Z'),
  ('L4.4', 'docs/lessons/week-04.md', 'Lesson 4 — What Is a Company Worth? (Mr. Market moves into your phone)', '0:10 — The shop on the corner', 'No slides yet — flip chart. Imagine buying the corner shop outright. What would you demand to see before naming a price? Let the room build the list: what it owns (stock, fittings, the van), what it owes (suppliers, the loan), what it takes in a year, what''s left after wages and light. Then the reveal: they have just invented the balance sheet and the income statement. Companies file exactly these, audited, every year, in public. A share is the corner shop cut into millions of slices — week 1''s napkin, now with documents. (Graham''s own version of this move — valuing the business, not the ticker — is Security Analysis''s whole premise; the 1940 edition''s epigraph is Horace: "Many shall be restored that now are fallen, and many shall fall that now are in honor." Read it aloud; it''s week 5''s mood.)', 143, '2026-11-12T13:40:44.802Z');
INSERT INTO notes (id, source, title, heading, body, words, seeded_at) VALUES
  ('L4.5', 'docs/lessons/week-04.md', 'Lesson 4 — What Is a Company Worth? (Mr. Market moves into your phone)', '0:25 — Four numbers, kitchen-table words', 'On the flip chart, one at a time, each with its question:
- EPS — of the year''s profit, how much belongs to one slice? (TII ch. 12, p. 310, warns how this number gets dressed up — one line now, the full warning in week 6''s narrative lesson.)
- Book value per share — if the company shut tonight, sold the lot and paid every debt, what''s left per slice?
- Current ratio — can it pay this year''s bills with this year''s money? Graham''s comfort line: about 2-to-1.
- Long-term debt vs working capital — is the mortgage bigger than the cushion?
No formulas yet beyond the words. The site computes; tonight is about what the numbers ask.', 120, '2026-11-12T13:40:44.802Z'),
  ('L4.6', 'docs/lessons/week-04.md', 'Lesson 4 — What Is a Company Worth? (Mr. Market moves into your phone)', '0:40 — Mr. Market', 'Tell it properly (TII ch. 8, p. 188ff): you own half a business; your partner is obliging but manic. Every day he names a price — some days giddy-high, some days despairing-low — and you are perfectly free to buy his half, sell him yours, or ignore him. His feelings are not information about the business. Then the 2026 update, straight from Zweig''s 75th-anniversary theme: Mr. Market now lives in your pocket. He pings you at breakfast, flashes red at lunch, throws confetti when you trade. The parable didn''t age — it got a push notification. The discipline drill they just did? That was a week of practising ignoring him. Margin of safety gets one sentence tonight as the bridge to week 5: never pay so much that being a bit wrong ruins you (ch. 20, p. 512, holds the full argument).', 142, '2026-11-12T13:40:44.802Z'),
  ('L4.7', 'docs/lessons/week-04.md', 'Lesson 4 — What Is a Company Worth? (Mr. Market moves into your phone)', '0:55 — Toolkit time: open the books', 'Phones out, no ration. Each student opens `/fundamentals/` + their homework company (or an adopted one). Tasks: (1) find the four cards and say aloud what each asks; (2) read the five-year table bottom row to top — has the dividend row ever gone blank?; (3) one journal line: "One number here surprised me because…". Point at the red/green Graham bars on the cards and say plainly: these are teaching thresholds from Graham''s 1972 revision of a 1949 book, printed so you can argue with them — next week we run them as a screen and argue properly. Note what the P/E card does for a loss-making year: it shows a dash, because a loss has no meaningful P/E. The toolkit refusing to compute nonsense is the lesson.', 128, '2026-11-12T13:40:44.802Z'),
  ('L4.8', 'docs/lessons/week-04.md', 'Lesson 4 — What Is a Company Worth? (Mr. Market moves into your phone)', '1:15 — The savers'' question', 'Name the room''s real starting point: most of you are savers wondering whether to become investors, with deposit rates and the property pages as your comparisons. Hold the course''s line: we don''t predict, and nothing here is advice — but we can say what a defensive investor demands before parting with savings: evidence, read from the books, with a margin for being wrong. Deposits ask no reading and pay accordingly; property arrives with a mortgage and no five-year table on a phone screen. What this course adds is the reading. (If this week''s Budget changed the tax treatment of savings or investments — see tutor notes — say only: "the rules just moved, week 11 prices it properly.")', 118, '2026-11-12T13:40:44.802Z'),
  ('L4.9', 'docs/lessons/week-04.md', 'Lesson 4 — What Is a Company Worth? (Mr. Market moves into your phone)', '1:25 — Homework + close', '(1) Read TII ch. 8 — Graham''s text and Zweig''s commentary (p. 188 and p. 213 in the course copy''s pagination); it''s the most important chapter in the book. (2) Journal: open your company''s books page twice this week; note one line that moved or surprised you — and resist Mr. Market both times. Close with the sentence.', 58, '2026-11-12T13:40:44.802Z'),
  ('L5.1', 'docs/lessons/week-05.md', 'Lesson 5 — The Graham Checklist (and the evening we argue with it)', 'Overview', '90 minutes · Phase 2, week 2 of 3 · Toolkit feature: the Graham screen `/screen` + the checklist card `/card`
Methodology: the seven defensive-investor tests from The Intelligent Investor ch. 14 (course copy p. 347; Zweig''s commentary p. 367), as Graham revised them in 1971–72; margin of safety from ch. 20 (p. 512). Chapter numbers hold in every edition.', 60, '2026-11-12T13:40:44.802Z'),
  ('L5.2', 'docs/lessons/week-05.md', 'Lesson 5 — The Graham Checklist (and the evening we argue with it)', 'By the end, students can', '1. State margin of safety in one sentence, and show how each of the seven tests is a version of it.
2. Read the checklist card: what each test asks, and which four rules are adapted (and why).
3. Run the screen, read a verdict row, and explain a failure in plain words.
4. Argue both sides: is a famous company''s failure a fault in the company, or in a test written in 1972?', 74, '2026-11-12T13:40:44.802Z'),
  ('L5.3', 'docs/lessons/week-05.md', 'Lesson 5 — The Graham Checklist (and the evening we argue with it)', '0:00 — Wall of Resulting + harvest', 'Nominate, vote, pin. Then the chapter 8 reading: where did they spot Mr. Market this week? (Expect notification screenshots. Pin the best one beside the Wall.) Then collect one books-page surprise per table.', 33, '2026-11-12T13:40:44.802Z');
INSERT INTO notes (id, source, title, heading, body, words, seeded_at) VALUES
  ('L5.4', 'docs/lessons/week-05.md', 'Lesson 5 — The Graham Checklist (and the evening we argue with it)', '0:10 — Margin of safety, in full', 'Last week it was one sentence. Tonight it gets the full idea (ch. 20, p. 512). The engineer''s version works on any room: a bridge rated for 30 tonnes carries 10-tonne lorries. You never know the true load, so you build the gap in. In investing, the gap is between what you pay and what the business is worth. The gap is there because you will sometimes be wrong. Write on the board: every test on tonight''s card is a different way of building in that gap.', 87, '2026-11-12T13:40:44.802Z'),
  ('L5.5', 'docs/lessons/week-05.md', 'Lesson 5 — The Graham Checklist (and the evening we argue with it)', '0:20 — Walk the card: the defensive screen''s seven tests', 'Hand out the printed cards. Go through the seven tests at kitchen-table pace, using the italic "why" line on each:
- Size: small firms break in bad years.
- Strength: can it pay the bills, and is the mortgage smaller than the cushion?
- Stability: has it never lost money?
- Dividends: has it handed over real cash for a decade?
- Growth: modest growth that has actually happened.
- P/E: don''t pay many years of profit up front.
- P/B: something solid behind the price.
Then the four adapted stamps, taught as a lesson in their own right:
- Graham asked for 10 years of earnings; free data holds 5.
- He asked for 20 years of dividends; our record holds about 15, so we ask for 10.
- His $100m size floor was in 1971 dollars; ×~8 for inflation gives $800m.
- His growth test was +⅓ over 10 years; we pro-rate that to our shorter window, which comes to +9%. (Strictly, his three-year averages sit seven years apart, so a stricter reading would be +13%. We chose 9% and say so on the card.)
Honest data use means saying out loud where your data runs short. Compare a tip-seller''s spreadsheet, which never tells you where its numbers ran out.', 212, '2026-11-12T13:40:44.802Z'),
  ('L5.6', 'docs/lessons/week-05.md', 'Lesson 5 — The Graham Checklist (and the evening we argue with it)', '0:35 — Predict first', 'Before anyone sees the screen: each student writes on a slip which three companies from the universe will pass all seven. Name, date, sealed. This is a decision-journal entry made before the outcome. Process first, then the reveal.', 38, '2026-11-12T13:40:44.802Z'),
  ('L5.7', 'docs/lessons/week-05.md', 'Lesson 5 — The Graham Checklist (and the evening we argue with it)', '0:40 — Run the screen', 'Project `/screen`. Read the tally boxes, then the survivor rows, then the near misses. Open the slips: how many predictions survived? Expect very few survivors. That''s the design: Graham wrote these tests to reject, and a universe of famous mega-caps is exactly where they bite hardest. Graham''s own result is the proof (p. 354): applied to the 30 Dow stocks at the end of 1970, only five passed — American Can, AT&T, Anaconda, Swift and Woolworth. Then tell them what happened next: Anaconda''s Chilean mines were expropriated within the year; Woolworth declined for decades. Passing the screen earns a reading, not safety. Hover a ✗ to show its numbers. Every mark can be explained from the books page, and that''s the standard. Read the Security Analysis epigraph again: "Many shall be restored that now are fallen, and many shall fall that now are in honor."', 145, '2026-11-12T13:40:44.802Z'),
  ('L5.8', 'docs/lessons/week-05.md', 'Lesson 5 — The Graham Checklist (and the evening we argue with it)', '0:55 — Argue in pairs', 'Each pair gets one survivor (or near miss) and one famous failure. If nothing survives and nothing nearly does, take the highest scorers instead (on the first run, Nvidia at 5/7) — the eight-company table in `week-05-reading-the-screen.md` is the ready-made material. Use a household name if possible: a tech giant, a carmaker, an aircraft maker, a bank. Three questions to answer:
1. Which tests did it fail, in plain words? (Read the numbers off the hover detail or the books page.)
2. Is the test right about this company, or out of date? Two modern frictions to hand them:
   - Buybacks shrink book equity, so P/B balloons.
   - Intangibles (brands, software, patents) barely appear on the balance sheet at all.
Banks and other financial companies show "–" on test 2 and are scored out of six. Graham''s financial-strength test is written "for industrial companies"; for financials he applied only the price tests (p. 361). The "–" is not a fail, and it doesn''t count against them. Zweig concedes the intangibles point himself (p. 374): brands, patents and goodwill are excluded from book value, so "most companies today are priced at higher price-to-book multiples than in Graham''s day". The objection comes from inside the book.
3. Does failing make it a bad investment, or just not a defensive one?

Report back: one sentence per pair. The course takes no side. The skill is arguing from the books rather than from the headlines.', 241, '2026-11-12T13:40:44.802Z'),
  ('L5.9', 'docs/lessons/week-05.md', 'Lesson 5 — The Graham Checklist (and the evening we argue with it)', '1:15 — What a screen can''t tell you', 'Four things no screen can show: whether management can be trusted; whether the business has a moat; what happens next; and why any number is what it is. The screen narrows the list. Reading decides. Zweig''s rule for the reading (p. 375): go to the company''s own reports and "read at least five years'' worth" — which is exactly what the books page puts in front of them. And his blunt corollary, quoted straight: if you''re not willing to do that, "you are too defensive to be buying individual stocks at all. Get yourself out of the stock-picking business and into an index fund, where you belong." His practical compromise (p. 367): keep 90% in an index fund and pick stocks with the other 10%. That is not advice from this course; it is what the book says, and it belongs in the room. Next week brings narrative ("explain this stock"), and with it the danger of stories that outrun the numbers.', 162, '2026-11-12T13:40:44.802Z'),
  ('L5.10', 'docs/lessons/week-05.md', 'Lesson 5 — The Graham Checklist (and the evening we argue with it)', '1:25 — Homework + close', '1. Read TII ch. 14: Graham''s text plus Zweig''s commentary (p. 347 and p. 367).
2. Journal a pre-mortem. Pick one survivor or near miss and answer: "It''s three years from now and this turned out badly. What most likely happened?" Before writing it, read that company''s five-year table on the books page — Zweig''s "five years'' worth".
3. Keep the card. It''s page two of the takeaway kit.
Close with the sentence.', 73, '2026-11-12T13:40:44.802Z'),
  ('L5R.1', 'docs/lessons/week-05-reading-the-screen.md', 'Reading the screen — teaching points from the first live runs', 'Overview', 'Tutor notes · Phase 2 · a companion to lesson 5 (and the grounding for lesson 6)
What this is. The Graham screen ran for the first time over real books on 12 October 2026 and over the complete 31-company universe on 13 October. These are the teaching points that came out of reading those results — each one tied to the page of* The Intelligent Investor (course copy, 2003 revised edition) it rests on. The numbers below are a dated snapshot: the pool widens after the value sweep, and the screen''s footer row shows the live counts. Keep this file as the record of the first result; Graham''s own first result (p. 354) was a dated snapshot too.', 119, '2026-11-12T13:40:44.802Z');
INSERT INTO notes (id, source, title, heading, body, words, seeded_at) VALUES
  ('L5R.2', 'docs/lessons/week-05-reading-the-screen.md', 'Reading the screen — teaching points from the first live runs', 'The result', 'Universe 31, all with books. Survivors 0 · near misses 0 · fail two or more 31. The closest thing to a survivor was Nvidia at 5/7, failing only the two price tests.
Test — 1 Size — 2 Strength — 3 Stability — 4 Dividends — 5 Growth — 6 P/E ≤ 15 — 7 P/B
Companies failing — 0 — 23 of 27 applicable — 4 — 9 — 15 — 29 — 30
Only Delta and Nike passed the P/E test; only Bank of America passed the book-value test; no company passed both.', 96, '2026-11-12T13:40:44.802Z'),
  ('L5R.3', 'docs/lessons/week-05-reading-the-screen.md', 'Reading the screen — teaching points from the first live runs', '1. Zero is the screen working', 'Graham says in so many words that his tests reject the famous growth companies: they are "exclusive in the opposite direction" (p. 349), shutting out the companies "whose shares sell at especially high multipliers" (p. 347). This universe is the 31 most famous companies in the world, chosen for two reasons that have nothing to do with value — students know them (Apple in Cork, Pfizer in Ringaskiddy), and the free data plan serves them. Those are the same reason: data providers whitelist what people search for, and people search for fame.
So "were we fishing in the wrong pool?" — yes, and Graham told us we would be. His own 1970 screen passed five of the thirty Dow stocks (p. 354): American Can, AT&T, Anaconda, Swift, Woolworth — the unglamorous. Two of the five went badly within years. A defensive screen run over the glamour end of the market and returning zero is not a broken screen. It is the screen doing the job it was written for.
In class: the 0:40 reveal. Put the prediction slips beside a zero and let that sit.', 185, '2026-11-12T13:40:44.802Z'),
  ('L5R.4', 'docs/lessons/week-05-reading-the-screen.md', 'Reading the screen — teaching points from the first live runs', '2. Two readings, both on the board — and which way the data leans', 'The lesson plan''s rule stands: if nothing survives, write both readings up — the market is expensive and the tests are dated — and don''t pick one for them. But the room can be shown which way the evidence leans. The "dated tests" argument is about book value: brands, patents and software don''t appear on the balance sheet, so P/B is high everywhere (Zweig concedes this himself, p. 374). That explains the 30 fails on test 7. It explains nothing about test 6: not one of these 31 trades below 15 times its three-year average earnings. Graham''s own looser rule — an earnings yield at least matching the AA bond yield (p. 350; Zweig''s footnote works it to a maximum P/E of 21.7 and a target of about 17 for 2003) — would still reject most of the 31 at today''s yields. Zweig found the same in 2003: only about 120 of the S&P 500 passed the 2:1 current-ratio test alone (p. 369).
In class: let them do Graham''s bond-yield arithmetic themselves with today''s AA yield. That is Graham arguing with Graham, and p. 349 says "the reader will have to decide this important question for himself."', 197, '2026-11-12T13:40:44.802Z'),
  ('L5R.5', 'docs/lessons/week-05-reading-the-screen.md', 'Reading the screen — teaching points from the first live runs', '3. The strength inversion', 'Who passed test 2, the financial-strength test? Nvidia, Alphabet, Meta, AMD, Tesla — cash-rich technology companies. Who failed it? Coca-Cola, Pepsi, Johnson & Johnson, Walmart, Costco, Apple — the dividend aristocrats. Graham''s test, written "for industrial companies" (p. 348), now rewards the growth companies and punishes the steady ones, because the modern consumer giant runs on thin working capital by design: retailers are paid before they pay suppliers, and buybacks are funded with long-term debt.
In class: the pairs question — is Apple''s 0.9 current ratio weakness, or efficiency? Both answers are defensible from the books. That is the point.', 100, '2026-11-12T13:40:44.802Z'),
  ('L5R.6', 'docs/lessons/week-05-reading-the-screen.md', 'Reading the screen — teaching points from the first live runs', '4. Eight companies, eight meanings of ✗ (1)', 'A screen reports that a test failed; it cannot report why. The first live table happened to contain every kind of why, which is what lesson 6 ("explain this stock") is built on:
Company — What the ✗ means — Graham
Nvidia 5/7 — Passes every business test, fails only on price. Not a bad company — a price that demands growth a defensive investor doesn''t pay for. — p. 349
Alphabet, Meta — Fail dividends because the policy began in 2024. A ten-year record is impossible for a two-year payer: a test that cannot apply yet, not weakness. — p. 348
Bank of America 4/6 — The only company to pass book value — banks trade near book, which is why Graham applied only the price tests to financials. Fails growth. — p. 361
Delta, Nike — The only P/E passes — "cheap for a reason." Delta''s earnings are cyclical and its dividend was suspended in 2020; Nike''s earnings are falling. The value-trap conversation. — p. 165 (Chrysler)
Coca-Cola, J&J — Fail strength on thin working capital. Weak, or efficient? — p. 348
Exxon — Fails growth because the base years (2022–23) were a windfall. Cyclical earnings are exactly why Graham averages three years. — p. 349
Boeing, Intel — 1/7 — fail everything but size. Size is the one test a mega-cap cannot fail. — p. 348', 229, '2026-11-12T13:40:44.802Z'),
  ('L5R.7', 'docs/lessons/week-05-reading-the-screen.md', 'Reading the screen — teaching points from the first live runs', '4. Eight companies, eight meanings of ✗ (2)', 'In class: assign one row per pair at 0:55. The report-back sentence is "our company failed test N because…", read off the books page, not the headlines.', 27, '2026-11-12T13:40:44.802Z'),
  ('L5R.8', 'docs/lessons/week-05-reading-the-screen.md', 'Reading the screen — teaching points from the first live runs', '5. Nobody is cheap on both price measures', 'Delta and Nike are cheap against earnings; Bank of America is cheap against assets; nobody is cheap against both. Graham''s two price tests measure different things — earnings power and asset backing — and the 22.5 product (p. 349) is his compromise for a company that is reasonable on both. A universe with no overlap at all is the sharpest single statement of "expensive" the screen can make.
Addendum, 17 Oct 2026. With the value tier in (universe 38), two companies pass both price tests: AT&T and Verizon. Both fail on the business side instead — AT&T on strength and stability (a 2022 loss), Verizon on strength and growth — so the table now holds three 5/7s with disjoint failures: Nvidia fails only on price; AT&T and Verizon fail only on quality. That is Graham''s trade-off in one screen, and Wells Fargo became the project''s first near miss (5/6, failing only P/E). The statement above stands for the famous 31; the pool was widened precisely to change it.', 168, '2026-11-12T13:40:44.802Z'),
  ('L5R.9', 'docs/lessons/week-05-reading-the-screen.md', 'Reading the screen — teaching points from the first live runs', '6. The dividend column is a history book', 'Nine fails on test 4, every one a fact: Alphabet and Meta began paying in 2024; Amazon, Tesla, Netflix, Adobe and AMD have never paid; Disney suspended 2020–23; Delta suspended in 2020. Zweig''s table (p. 372) lists companies that have paid every year since the 1800s — Bank of America since 1903 — and the screen found the data agreed. A ten-year record is a statement about the past, not a judgment about the future; it is on the card because Graham wanted evidence of real cash handed over, year after year (the card''s own words, not his).', 98, '2026-11-12T13:40:44.802Z');
INSERT INTO notes (id, source, title, heading, body, words, seeded_at) VALUES
  ('L5R.10', 'docs/lessons/week-05-reading-the-screen.md', 'Reading the screen — teaching points from the first live runs', '7. The stability column is the Boeing lesson', 'Four fails on test 3, all real loss years: Amazon 2022, GE 2021–22, Boeing every year since 2019, Intel 2024. "Has it never lost money?" is the simplest question on the card and the one most students have never asked of a famous company.', 44, '2026-11-12T13:40:44.802Z'),
  ('L5R.11', 'docs/lessons/week-05-reading-the-screen.md', 'Reading the screen — teaching points from the first live runs', '8. Verify before you interpret (the method, applied to itself)', 'The first screen, on 12 October, showed 21 companies with books and ten "blocked." That zero would have been a false result: the gap turned out to be the toolkit hitting a platform limit, not the companies failing. Before anyone interpreted the zero, two checks were made — the dividend record''s order (Coca-Cola, J&J and Pfizer showing ✓ in column 4 proved the record was stored the right way round) and the missing ten (fixed, refetched, screened). Only then was the zero called real. One more thing worth telling the room: a prediction was written down that Exxon would pass both price tests on the full data. It didn''t. The prediction stays on the record, graded by the data — which is what the decision journal asks of them.
In class: this is the week-4 reconciliation habit at scale. A result is only as good as the record behind it; the toolkit''s diary (`fetch_log`) is where the record lives.', 159, '2026-11-12T13:40:44.802Z'),
  ('L5R.12', 'docs/lessons/week-05-reading-the-screen.md', 'Reading the screen — teaching points from the first live runs', '9. Two investors — effort, not risk appetite (1)', 'Graham''s distinction is not about nerve. The defensive investor wants "freedom from effort, annoyance, and the need for making frequent decisions"; "the determining trait of the enterprising investor is his willingness to devote time and care" (p. 6). His enterprising criteria (pp. 385–386) show what the extra effort buys: a cheapness filter first (nine times earnings or less), then five tests relaxed from the defensive set — current ratio 1.5, debt up to 110% of working capital, no deficit in five years, "some current dividend", latest earnings above four years earlier — and no size floor: "small companies may afford enough safety if bought carefully and on a group basis." One test is stricter: price under 120% of net tangible assets. The enterprising investor is a bargain-hunter willing to read small, dull companies the market has walked past. His 1970 list (Table 15-1, p. 387) is Aberdeen Mfg., Allied Mills and Big Bear Stores.', 154, '2026-11-12T13:40:44.802Z'),
  ('L5R.13', 'docs/lessons/week-05-reading-the-screen.md', 'Reading the screen — teaching points from the first live runs', '9. Two investors — effort, not risk appetite (2)', 'Two consequences for the course. Small companies fail the defensive screen''s size test by design — the two screens see different pools, which is the cleanest way to show what "willing to engage" buys. And Graham''s conditions for small companies are the brief for the paper portfolio in weeks 8–9: "on a group basis" (p. 386), and bargains pay "if you can find enough of them to make a diversified group, and if you don''t lose patience" (p. 392). Zweig adds the house rules: practise for a year on paper before real money (pp. 396–397), and cap stock-picking at 10% of the portfolio with the rest in an index fund (p. 397) — which is what this course is.', 119, '2026-11-12T13:40:44.802Z'),
  ('L5R.14', 'docs/lessons/week-05-reading-the-screen.md', 'Reading the screen — teaching points from the first live runs', '10. Affordable is not the same as cheap', 'A €10,000 pot makes share price matter — a €2,000 position in a $900 share is two shares and no granularity — but that is a sizing problem for week 8, not a valuation signal. Graham on low-priced shares: "this fact is not truly important" (p. 385). The value pool is weighted to sub-$100 names for the sizing reason; the screens never look at the share price itself.', 68, '2026-11-12T13:40:44.802Z'),
  ('L5R.15', 'docs/lessons/week-05-reading-the-screen.md', 'Reading the screen — teaching points from the first live runs', 'Where each point lands', '- Lesson 5, 0:40 run the screen → points 1, 2, 5. 0:55 argue in pairs → points 3, 4, 6, 7 (one row of the table per pair). 1:15 what a screen can''t tell you → point 8.
- Lesson 6, "explain this stock" → point 4 is the grounding set; the explainer''s job is to say which kind of ✗ a company has, and what would have to change — never buy or sell.
- The enterprising screen (shipped in v0.6.0: `/screen/enterprising`, card page 2) → point 9; tutor notes in `the-enterprising-screen.md`. Point 10 belongs to that segment and returns in week 8.
- Pre-check before class: the footer row on `/screen` gives the live fail counts; compare them with the table at the top of this file and note what moved.
Education, not advice. A survivor is a company worth reading about — not a recommendation to buy anything.', 152, '2026-11-12T13:40:44.802Z'),
  ('L5E.1', 'docs/lessons/the-enterprising-screen.md', 'The enterprising screen — tutor notes', 'Overview', 'Phase 2 · a segment for lesson 5 or 6 (25 minutes) · grounding for the paper portfolio in weeks 8–9
What it is. `/screen/enterprising` runs Graham''s second checklist over the same books as the defensive screen. Its source is The Intelligent Investor, ch. 15, "A Winnowing of the Stock Guide" (course copy pp. 385–386). The printable version is page 2 of `/card`.', 63, '2026-11-12T13:40:44.802Z'),
  ('L5E.2', 'docs/lessons/the-enterprising-screen.md', 'The enterprising screen — tutor notes', 'The six requirements, and what changed from ch. 14', '— Enterprising (ch. 15) — Defensive (ch. 14) — Direction
1 — P/E ≤ 9 on the latest year — P/E ≤ 15 on the 3-year average — stricter, and applied first
2 — Current ratio ≥ 1.5; debt ≤ 110% of working capital — ≥ 2; ≤ 100% — relaxed
3 — No deficit in 5 years — Earnings in each of 10 years — relaxed
4 — Some current dividend — 20 years uninterrupted — relaxed
5 — Latest EPS above four fiscal years earlier (the oldest of the five years held — Graham''s 1970 v 1966) — +⅓ over ten years — relaxed
6 — Price < 120% of net tangible assets — P/B ≤ 1.5 (or P/E × P/B ≤ 22.5) — stricter: goodwill doesn''t count
— — No size test (p. 386) — Sales ≥ $100m (1971) — removed
The point to make in one sentence: the enterprising investor relaxes on quality and record, and tightens on price. The extra effort pays for reading companies that the defensive tests would reject, but only at bargain prices.', 181, '2026-11-12T13:40:44.802Z');
INSERT INTO notes (id, source, title, heading, body, words, seeded_at) VALUES
  ('L5E.3', 'docs/lessons/the-enterprising-screen.md', 'The enterprising screen — tutor notes', 'Graham''s definitions (put them on the board)', '- Defensive: wants "freedom from effort, annoyance, and the need for making frequent decisions" (p. 6).
- Enterprising: "willingness to devote time and care" (p. 6). This is about effort, not nerve, and the course has decided not to call it "risk appetite."
- Small companies "may afford enough safety if bought carefully and on a group basis" (p. 386).
- The screen gives a list, not a choice. From about 150 survivors Graham expected "a third selection of, say, one out of five" by judgment (p. 386). That is why the page says candidate, not survivor.', 97, '2026-11-12T13:40:44.802Z'),
  ('L5E.4', 'docs/lessons/the-enterprising-screen.md', 'The enterprising screen — tutor notes', 'How the toolkit adapts it (openly)', '- Test 1 uses the latest fiscal year''s diluted EPS, because the Stock Guide''s latest-12-months figure is not held. This is the only test marked adapted on the card.
- "Debt" is read as long-term debt, the figure held.
- "Some current dividend" means an ex-date within the last 12 months.
- Financial companies skip test 2 (Graham''s parenthesis: "for industrial companies") and are scored out of 5.
- Tangible book is equity minus goodwill and intangibles, per diluted share. It fills as the accounts rotation refetches each company after v0.5.3; until then the column shows "?".', 97, '2026-11-12T13:40:44.802Z'),
  ('L5E.5', 'docs/lessons/the-enterprising-screen.md', 'The enterprising screen — tutor notes', 'The worked example: Ethan Allen (ETD), 14 Oct 2026', 'ETD was the test company for VC-13/14. It is a small, dull furniture maker that FMP''s free plan won''t serve. From its FY2026 10-K at the 14 Oct close of $20.06:
- P/E 20.06 ÷ 1.56 = 12.9 → fails test 1. Cheap by defensive standards, not cheap enough for Graham''s enterprising cut.
- Strength CR 305.5 ÷ 148.4 = 2.06, no debt → passes. Stability passes. Dividend current → passes.
- Growth FY2026 1.56 vs FY2022 4.05 (EDGAR) → fails. Earnings have fallen since the post-Covid peak.
- Tangible book (471.5 − 45.1)m ÷ 25.58m = $16.66, so price is 1.20× → fails "less than 120%" by a whisker.
So ETD fails three tests (1, 5 and 6) and passes three, which makes it not a candidate. It is still a strong teaching case: a strong balance sheet, a real dividend, and earnings that peaked and are falling. Ask the room: is the market wrong about ETD, or right? (The figures will move; recompute on the day from the books page.)', 172, '2026-11-12T13:40:44.802Z'),
  ('L5E.6', 'docs/lessons/the-enterprising-screen.md', 'The enterprising screen — tutor notes', 'In class', '1. 0:00 Open both screens side by side. Ask: who passes one screen and fails the other, and why? (Expect the value tier, Ford and Citi, to look different on the two.)
2. 0:10 The table above: relaxed versus stricter. Ask where the price tests got tougher.
3. 0:15 ETD worked through on the board with a calculator: "fails by a whisker" is a decision too.
4. 0:22 Graham''s third selection: candidates are a reading list. Link to the weeks 8–9 portfolio: "on a group basis" (p. 386), and Zweig''s 10% cap with a year on paper (pp. 396–397).
Education, not advice. A candidate is a company worth reading about, never a recommendation.', 113, '2026-11-12T13:40:44.802Z'),
  ('L6.1', 'docs/lessons/week-06.md', 'Lesson 6 — Numbers into Narrative (and the evening we audit a story)', 'Overview', '90 minutes · Phase 2, week 3 of 3 · Toolkit feature: "Explain this stock" `/explain/:ticker` — a numbered fact sheet, a short story written from it, and the checks that bind the story to the sheet. Also taught tonight: the enterprising screen `/screen/enterprising` and page 2 of the card.
Methodology: Graham on the two investors (TII p. 6), the enterprising investor''s winnowing (ch. 15, pp. 385–387), the Chrysler caveat on low multipliers (ch. 7, p. 165), Mr. Market (ch. 8, p. 188; Zweig p. 213), and Zweig''s rule to read five years of a company''s own reports (p. 375). Chapter numbers hold in every edition; page numbers are the course copy.', 112, '2026-11-12T13:40:44.802Z'),
  ('L6.2', 'docs/lessons/week-06.md', 'Lesson 6 — Numbers into Narrative (and the evening we audit a story)', 'By the end, students can', '1. Say what the enterprising investor relaxes and what he tightens, and why a small dull company can be a candidate on one screen and a fail on the other.
2. Read an AI-written explanation of a company against its fact sheet, sentence by sentence, and find the claim the sheet does not support.
3. Tell a number that is on the record from a number that is in the story, and say which of Graham''s three P/Es a figure is.
4. Answer, in their own words, "why not just use Yahoo Finance?"', 93, '2026-11-12T13:40:44.802Z'),
  ('L6.3', 'docs/lessons/week-06.md', 'Lesson 6 — Numbers into Narrative (and the evening we audit a story)', '0:00 — Harvest: the pre-mortems', 'Three volunteers read theirs. Listen for the pattern: the good ones name a number that would have to move (a loss year, a debt figure, a dividend cut); the weak ones tell a story with no number in it. Say so, kindly. That difference is tonight.', 46, '2026-11-12T13:40:44.802Z'),
  ('L6.4', 'docs/lessons/week-06.md', 'Lesson 6 — Numbers into Narrative (and the evening we audit a story)', '0:10 — The two investors', 'Graham''s distinction is effort, not nerve (p. 6): the defensive investor wants "freedom from effort"; the enterprising one has "willingness to devote time and care". Project `/screen/enterprising` beside `/screen`. Walk the table from `the-enterprising-screen.md`: relaxed on quality and record (1.5× instead of 2×, five years instead of ten, "some current dividend" instead of twenty years), stricter on price (nine times earnings or less, first; under 120% of tangible book), and no size test at all (p. 386).
Then read the room''s numbers off the footer. On the 17 Oct run: 37 of 38 failed the first cut and 38 of 38 failed tangible book — nothing in our pool is priced within 120% of what you could touch, banks included. The one company through the first cut (AT&T) failed three others. Ask: who passes one screen and fails the other, and why? (Alphabet and Meta pass "some current dividend" and fail the ten-year record: same history, two correct answers.) Close with Graham''s own numbers: about 150 of 4,500 passing all six in 1970, then "a third selection … one out of five" by judgment (p. 386). Candidates are a reading list.', 191, '2026-11-12T13:40:44.802Z');
INSERT INTO notes (id, source, title, heading, body, words, seeded_at) VALUES
  ('L6.5', 'docs/lessons/week-06.md', 'Lesson 6 — Numbers into Narrative (and the evening we audit a story)', '0:35 — Stories versus numbers', 'Every tip is a story. Mr. Market "lets his enthusiasm or his fears run away with him" (ch. 8), and in 2026 he lives in your pocket. The course''s defence is not cynicism but a habit: every sentence about a company should point at a number on the record, and the number should be one you can find yourself. Tonight the toolkit models that habit, and then we check whether it kept it.', 73, '2026-11-12T13:40:44.802Z'),
  ('L6.6', 'docs/lessons/week-06.md', 'Lesson 6 — Numbers into Narrative (and the evening we audit a story)', '0:45 — Explain this stock, live', 'Project `/explain/` for the highest scorer. Read the page top to bottom: the two verdict chips; the story, four short paragraphs with small fact tags after each; the source line (who wrote it, when, from the cache or fresh, how many tokens, and whether the checks were clean); then the fact sheet the story was written from; what would have to change, in numbers; what kind of ✗.
Say plainly what happened: a numbered fact sheet was built from the books and both screens (no AI involved); an AI was given that sheet and nothing else, told to use only the facts, to tag every paragraph with the facts it rests on, and never to recommend; and then the toolkit checked the answer — any number not on the sheet, any fact id that doesn''t exist, any advice-shaped language gets flagged on the page. Click "Read the plain version instead" to show the course''s own template sentences from the same sheet. Two tellings, one record.', 165, '2026-11-12T13:40:44.802Z'),
  ('L6.7', 'docs/lessons/week-06.md', 'Lesson 6 — Numbers into Narrative (and the evening we audit a story)', '0:55 — Audit the story, in pairs', 'Each pair takes a printed explain page. Three jobs, in order:
1. Trace. For each sentence, find the fact tag and read the fact. Does the fact support the sentence? Mark ✓, ✗ (not supported) or ? (true as far as you know, but not on the sheet).
2. Catch. Is there a number anywhere in the story that is not on the sheet? A claim about why something happened? A word that nudges ("cheap", "opportunity", "safe")? The toolkit catches invented numbers and advice-shaped phrases (a list it can be shown, never a complete one); it cannot catch a wrong word ("fails" where the sheet says "near miss") or a why the sheet never gave. That is your job.
3. Rewrite. One sentence of your own, better than the AI''s, citing a fact.
Report back: one catch per pair. Expect some pages to be clean, and say so: a clean page is not a reason to stop checking; it''s what checking looks like when it passes.', 166, '2026-11-12T13:40:44.802Z'),
  ('L6.8', 'docs/lessons/week-06.md', 'Lesson 6 — Numbers into Narrative (and the evening we audit a story)', '1:15 — The three P/Es', 'Pick one company. Open its books page and its Yahoo (or Google) Finance page side by side. Find three P/E ratios: Yahoo''s trailing figure, our "latest year" figure, our "three-year average" figure. All three are "right". Ask which one Graham asked for in ch. 14 (the three-year average, p. 349) and which in ch. 15 (the latest twelve months, p. 385), and show a company whose verdict changes with the choice (GM on the 16 Oct books: 14.8× on the average passes the defensive test; 25.6× on the charge year fails the enterprising cut). Then the scripted answer to the question that produced this exercise, below.', 106, '2026-11-12T13:40:44.802Z'),
  ('L6.9', 'docs/lessons/week-06.md', 'Lesson 6 — Numbers into Narrative (and the evening we audit a story)', '1:25 — Homework + close', '1. Write your own explanation, 120 words, of one company from its fact sheet alone, no AI, every sentence tagged with a fact id. Bring it printed.
2. Read TII ch. 15, pp. 385–387 (the winnowing and Table 15-1) and ch. 7, p. 165 (Chrysler).
3. Journal: the story I was told this week, and the number I found that checked it.
Close with the sentence.', 66, '2026-11-12T13:40:44.802Z'),
  ('L7.1', 'docs/lessons/week-07.md', 'Lesson 7 — Why Systems Beat Gut Feel (and the evening a rule reads every company the same way)', 'Overview', '90 minutes · Phase 3, week 1 of 3 · Toolkit feature: the signal engine — Robert Carver''s 16-day / 64-day moving-average crossover run nightly over the whole universe (`/signals`), the two averages drawn on every price chart (`/prices/:ticker`), and the series behind them (`/api/signals/:ticker`, `/api/prices/:ticker?csv=1` for a spreadsheet).
Methodology: Carver''s Starter System (Leveraged Trading, 2019 — the opening rule, instrument risk) and his Systematic Trading (2015, ch. 1 "The Flawed Human Brain"; ch. 7 "Forecasts": the EWMAC rule and its scalar); the evidence on individual investors (Barber & Odean 2000; Odean 1998); the evidence on trend following (Moskowitz, Ooi & Pedersen 2012; Hurst, Ooi & Pedersen 2017). Page anchors for the two Carver books are to be added from the course copies (OI-40).
Phase 2 gave the course rules for what — which companies are worth reading. Phase 3 gives it rules for when — when a rule, applied the same way every night, says a price is trending and when it says it is not — and, in weeks 8 and 9, how much a rule would let you hold and where it would make you stop. Nothing in Phase 3 picks a company. The screens still do that. The signal is a second, independent reading of the same share: the books say what it is; the price says what the crowd has been doing with it.', 229, '2026-11-12T13:40:44.802Z'),
  ('L7.2', 'docs/lessons/week-07.md', 'Lesson 7 — Why Systems Beat Gut Feel (and the evening a rule reads every company the same way)', 'By the end, students can', '1. Explain, in their own words, why a written rule applied by a machine beats a human reacting to the news — and name two of the biases the evidence finds in people who trade on feel.
2. Compute, on paper or in a spreadsheet, a 16-day EWMA, a 64-day EWMA, and the forecast the toolkit prints, from a list of closes.
3. Say what instrument risk is (the annualised volatility of a share), read it off the signals page, and say why everything in Phase 3 hangs off that one number.
4. Read a long/flat signal as the output of a rule and not as advice: "the rule is long" is a statement about 64 days of closes, not about the company or about you.', 126, '2026-11-12T13:40:44.802Z'),
  ('L7.3', 'docs/lessons/week-07.md', 'Lesson 7 — Why Systems Beat Gut Feel (and the evening a rule reads every company the same way)', '0:00 — Harvest: the 120-word explanations', 'Two read aloud. Listen for the sentence that has no fact tag; there is usually one. Then the ANDE page from the toolkit''s own diary: the AI wrote revenue as 11.2 billion where the sheet said 11.3, and the toolkit flagged it (24 Oct). The room''s exercise, done by the machine, on itself. Tonight we turn from reading to deciding — and the first decision is who decides.', 68, '2026-11-12T13:40:44.802Z');
INSERT INTO notes (id, source, title, heading, body, words, seeded_at) VALUES
  ('L7.4', 'docs/lessons/week-07.md', 'Lesson 7 — Why Systems Beat Gut Feel (and the evening a rule reads every company the same way)', '0:10 — Predict first', 'Slips out, before anyone sees a chart. Three names you believe are going up, three going down. Fold. They come back at 0:45.', 23, '2026-11-12T13:40:44.802Z'),
  ('L7.5', 'docs/lessons/week-07.md', 'Lesson 7 — Why Systems Beat Gut Feel (and the evening a rule reads every company the same way)', '0:15 — Why systems beat gut feel (1)', 'Carver''s first chapter is called "The Flawed Human Brain", and he means every brain, including his own. The evidence, in three findings the class can carry away:
- People who trade on feel trade too much, and it costs them. Barber and Odean read the records of 66,000 households at a US discount broker, 1991–96: the fifth that traded most earned 11.4% a year against the market''s 17.9%. Overconfidence, measured in commissions.
- People sell their winners and keep their losers. Odean (1998), the same kind of records: investors were about 50% more likely to sell a share showing a gain than one showing a loss — the disposition effect, loss aversion with a brokerage account.
- A rule has none of this. It cannot be overconfident, it does not feel a loss, it does not read the news, and it does the same thing on a bad night as on a good one. What it can be is wrong — openly, measurably, and in a way you can test before you trust it.', 174, '2026-11-12T13:40:44.802Z'),
  ('L7.6', 'docs/lessons/week-07.md', 'Lesson 7 — Why Systems Beat Gut Feel (and the evening a rule reads every company the same way)', '0:15 — Why systems beat gut feel (2)', 'That last line is the whole of Phase 3: not that rules are right, but that rules can be checked and gut feel cannot. The toolkit''s rule was checked three ways before tonight: against Carver''s book (the tutor''s copies — OI-40), against his own open-source code (the constants are his), and against a spreadsheet re-implementation (VC-19, done before this class). Nobody leaves their brain at the door: you check the rule; the rule checks the price.', 76, '2026-11-12T13:40:44.802Z'),
  ('L7.7', 'docs/lessons/week-07.md', 'Lesson 7 — Why Systems Beat Gut Feel (and the evening a rule reads every company the same way)', '0:35 — One instrument, one rule: the arithmetic (1)', 'Carver''s Starter System is deliberately small: one instrument, one opening rule. The rule, in full, on the board:
- λ = 2 ÷ (span + 1). For 16 days λ = 2/17 = 0.117647…; for 64 days λ = 2/65 = 0.030769…. Use the fractions, not a four-place rounding — four places moves the last digit of the worked example.
- EWMA today = λ × today''s close + (1 − λ) × yesterday''s EWMA. Start both at the first close.
- σ = the exponentially weighted standard deviation of daily price changes (span 35 — Carver''s default).
- forecast = 3.75 × (EWMA₁₆ − EWMA₆₄) ÷ σ, capped at ±20. The 3.75 is Carver''s scalar: it makes the average size of the forecast about 10, so that +20 means "as strong as trends get".
- State: forecast above zero → LONG; otherwise FLAT. The course''s adaptation: long-only, no shorts, no leverage — a community class in cash equities.
- Instrument risk = σ of daily percentage returns × 16 (√256 trading days), as a percentage a year.', 178, '2026-11-12T13:40:44.802Z'),
  ('L7.8', 'docs/lessons/week-07.md', 'Lesson 7 — Why Systems Beat Gut Feel (and the evening a rule reads every company the same way)', '0:35 — One instrument, one rule: the arithmetic (2)', 'Do three days of it by hand with closes 10, 11, 12: EWMA₁₆ goes 10 → 10.1176 → 10.3391; EWMA₆₄ goes 10 → 10.0308 → 10.0914. The fast average moves first. That is the whole idea: a crossover is the fast average overtaking the slow one, which only happens after a trend has been going for a while. The rule is late on purpose; being late is what filters the noise.', 71, '2026-11-12T13:40:44.802Z'),
  ('L7.9', 'docs/lessons/week-07.md', 'Lesson 7 — Why Systems Beat Gut Feel (and the evening a rule reads every company the same way)', '0:45 — The signals page, live, and the slips', 'Project `/signals`. Read the tally: how many long, how many flat, how many warming up (the small caps — fewer than 128 closes stored). Open one chart (`/prices/AAPL`, 1y): the blue 16-day line, the red dashed 64-day line, the green and grey strip underneath — green where the rule was long, grey where flat — and the hover on the strip for the dates. Count the flips over five years on `/api/signals/AAPL` → `summary.flips`.
Then the slips. Each student reads their six names against the page. Keep a tally on the board: agreed with the rule / disagreed. Expect the room to be right about half the time, which is the point: the rule is also right about half the time on any one day — the difference is that it will do the same thing tomorrow, and you will not.', 141, '2026-11-12T13:40:44.802Z'),
  ('L7.10', 'docs/lessons/week-07.md', 'Lesson 7 — Why Systems Beat Gut Feel (and the evening a rule reads every company the same way)', '1:00 — Instrument risk: the number everything hangs off', 'Sort the page by instrument risk in your head: the household names near 20–30% a year, the small caps at 40% and up. Say what the number means: a share with 30% instrument risk moves about 30% a year, two years in three — up or down. Next week that number becomes a position size (a volatile share gets a smaller holding) and a stop (half the annual risk below the high). Tonight it is enough that students can read it and rank by it.', 85, '2026-11-12T13:40:44.802Z'),
  ('L7.11', 'docs/lessons/week-07.md', 'Lesson 7 — Why Systems Beat Gut Feel (and the evening a rule reads every company the same way)', '1:10 — The spreadsheet', 'Pairs: the five-year CSV open (`?days=1900&csv=1`). Columns: date, adj_close. Add EWMA₁₆, EWMA₆₄, the price change, σ (the EW variance recursion, then its square root), forecast, state — the recipe is in the tutor''s VC-19 notes. The last row must match `/api/signals/<ticker>` → `latest`: the averages and σ to six decimals, the forecast to two. It will. The point of the exercise is not the arithmetic; it is that you can reproduce the machine''s answer, which is what makes it a rule and not an oracle.', 85, '2026-11-12T13:40:44.802Z');
INSERT INTO notes (id, source, title, heading, body, words, seeded_at) VALUES
  ('L7.12', 'docs/lessons/week-07.md', 'Lesson 7 — Why Systems Beat Gut Feel (and the evening a rule reads every company the same way)', '1:25 — Homework + close', '1. Write the rule in your own words, five lines, no symbols, as you would explain it to a friend. Bring it.
2. Pick your one instrument from the universe — the company you would follow with this rule for the rest of the course — and write why in the journal. Not the one you like: the one whose history you have read (its books page, its chart, its flips).
3. Read the Starter System''s opening-rule and instrument-risk chapters in Leveraged Trading (course copy; pages per the tutor''s list). Optional, for the science: Hurst, Ooi & Pedersen, "A Century of Evidence on Trend-Following Investing" (free on AQR''s site).
Close with the sentence.', 113, '2026-11-12T13:40:44.802Z'),
  ('L8.1', 'docs/lessons/week-08.md', 'Lesson 8 — How Much to Bet (and the ticket that makes you write down why)', 'Overview', '90 minutes · Phase 3, week 2 of 3 · Toolkit feature: Carver''s sizing and stop — the position-size calculator (`/size`, `POST /api/position-size`), paper tickets with a compulsory decision-journal entry (`/tickets/<code>`, `POST /api/tickets`), and the stop tracked nightly against the closes after the signal pass.
Methodology: Carver''s Starter System (Leveraged Trading, 2019 — risk targeting, position sizing, the stop-loss closing rule, minimum capital; the unleveraged variant, leverage factor 1) and Systematic Trading (2015, ch. 9 "Volatility targeting" and ch. 10 "Position sizing"); the course''s own numbers where the book leaves a choice are decision 19 in the syllabus. Page anchors for the two books are the tutor''s, from the course copies (OI-40).
Week 7 gave the course a rule for when: the 16/64 crossover, long or flat, read the same way every night. Tonight is how much — and how much is the question that separates a rule from a tip. A tip says "buy Apple". A rule says: at this volatility, with this account, this many shares; the stop here; the cost this; and if the account is too small for the share, say so and hold nothing. Then it makes you write down why before it accepts the ticket.', 201, '2026-11-12T13:40:44.802Z'),
  ('L8.2', 'docs/lessons/week-08.md', 'Lesson 8 — How Much to Bet (and the ticket that makes you write down why)', 'By the end, students can', '1. Explain risk targeting in a sentence — the account should move about 12% a year, so a share that moves more gets less of the account — and say why the target is modest.
2. Size a position by hand from three numbers (account, price, instrument risk) and place the first stop; reproduce the calculator''s line for one company.
3. Say what the stop-loss rule is (half the annual instrument risk below the highest close since entry, the gap fixed at entry, the level only ever rising) and why a close below it is a decision already made.
4. Write a paper ticket on their own page — the rule''s size, a journal entry of at least twenty characters — and read a refusal as the rule speaking, not the tutor.', 132, '2026-11-12T13:40:44.802Z'),
  ('L8.3', 'docs/lessons/week-08.md', 'Lesson 8 — How Much to Bet (and the ticket that makes you write down why)', '0:00 — Harvest: the rule in your words, and your one instrument', 'Three read aloud. Listen for "the fast average overtakes the slow one" in plain words — the sentence the week was for. Then round the room: the instrument each student chose and why. Write the tickers on the board; they come back at 1:00 when the tickets are written.', 49, '2026-11-12T13:40:44.802Z'),
  ('L8.4', 'docs/lessons/week-08.md', 'Lesson 8 — How Much to Bet (and the ticket that makes you write down why)', '0:10 — Why 12%? Risk targeting (1)', 'Carver''s Starter System starts not with "what to buy" but with "how much should my account move?" — the risk target. The course''s answer is his: 12% a year. Three things to say about it:
- It is the account''s volatility, not a return. A 12% risk target means the account''s value typically moves about 12% a year — up or down — the way instrument risk describes a share. Nobody promised 12% a year gained.
- It is modest on purpose. Carver''s reasoning (the Starter System chapter; the course takes the number): a trend rule''s expected reward per unit of risk is small — about a quarter — and betting the full amount that arithmetic allows ruins you on the way to the long run; he halves it. The worst years at a 12% target are survivable, which is the whole point of a target.
- It is the dial everything else turns on. A share that moves 24% a year gets half the account; a share that moves 6% would need twice the account, which a cash account cannot do. The rule says what you can hold once the target is set; the target is the only number of opinion in the system, and it is written down first.', 211, '2026-11-12T13:40:44.802Z'),
  ('L8.5', 'docs/lessons/week-08.md', 'Lesson 8 — How Much to Bet (and the ticket that makes you write down why)', '0:10 — Why 12%? Risk targeting (2)', 'Scripted answer — "Why not more when I''m sure?": "Because being sure is the thing week 7 measured. The target is the same on the night you are sure and the night you are not; that is what makes it a rule."', 42, '2026-11-12T13:40:44.802Z'),
  ('L8.6', 'docs/lessons/week-08.md', 'Lesson 8 — How Much to Bet (and the ticket that makes you write down why)', '0:25 — The arithmetic, in full (1)', 'On the board, with the calculator open at `/size`:
- Target exposure = account × risk target ÷ instrument risk. $10,000 × 12 ÷ 18.18 = $6,600.66 for Apple (instrument risk 18.18% on the 29 Oct close, from the signals page).
- Whole shares = the number that fits. $6,600.66 ÷ $348.91 = 18.9 → 18 shares, $6,280.38 — 62.8% of the account, carrying 62.8% × 18.18% = 11.42% a year. Just under target; whole shares always land under. The size does not change with the forecast''s strength: the Starter System holds the full position while its rule is on (Carver''s full system scales by the forecast — a later refinement, not in the course).
- Capped at the account. A share at 6% a year would ask for $20,000 of a $10,000 account; the cash account holds $10,000 and accepts 6%. No leverage in this class — the reason is the next slide.
- Three companies, one account, so the room sees the dial turn: Coca-Cola (21.11%, $94.08): $5,684.51 → 60 shares, $5,644.80, 11.92%. Microsoft (22.55%, $530.14): $5,321.51 → 10 shares, $5,301.40, 11.95%. The more it moves, the less you hold. Nothing about the companies entered the arithmetic.', 199, '2026-11-12T13:40:44.802Z'),
  ('L8.7', 'docs/lessons/week-08.md', 'Lesson 8 — How Much to Bet (and the ticket that makes you write down why)', '0:25 — The arithmetic, in full (2)', 'Pairs: each pair sizes its own instrument on paper from the signals page''s two numbers, then checks against `/size`. The calculator shows every line and its "how", so a disagreement is a row to find.', 35, '2026-11-12T13:40:44.802Z');
INSERT INTO notes (id, source, title, heading, body, words, seeded_at) VALUES
  ('L8.8', 'docs/lessons/week-08.md', 'Lesson 8 — How Much to Bet (and the ticket that makes you write down why)', '0:40 — The stop (1)', 'The Starter System has one closing rule: the trailing stop.
- The gap: half the annual instrument risk, in price: ½ × 18.18% × $348.91 = $31.72 for Apple. Fixed on the day you enter; it does not move with tonight''s volatility.
- The level: the highest close since entry, minus the gap. On day one, $348.91 − $31.72 = $317.19. If the share closes at $360, the stop is $328.28. It only ever rises.
- The rule: a close at or below the stop closes the position — at the next decision, with a ticket and a journal line. Not at the next crash headline; not "I''ll give it a day".
- Why half the annual risk? A stop too tight is hit by noise — the ordinary 1–2% days — and churns; too loose and a trend''s end costs most of what the trend made. Carver''s choice for a rule as slow as 16/64 is half a year''s movement; the course takes it. (The book''s exact figure and reasoning: tutor, OI-40.)
- Why the rule''s flip doesn''t close: the Starter System opens on the crossover and closes on the stop only; a long that turns flat on the signals page is information, not an order. Students will ask; say what the course does and why (decision 19).', 219, '2026-11-12T13:40:44.802Z'),
  ('L8.9', 'docs/lessons/week-08.md', 'Lesson 8 — How Much to Bet (and the ticket that makes you write down why)', '0:40 — The stop (2)', '- After a close (the stop''s, or one you chose): no re-entry on the same signal. The rule must go flat and then long again — a fresh crossover on or after the day you closed — before the next opening ticket. The toolkit refuses the other kind with a sentence.', 51, '2026-11-12T13:40:44.802Z'),
  ('L8.10', 'docs/lessons/week-08.md', 'Lesson 8 — How Much to Bet (and the ticket that makes you write down why)', '0:50 — Costs, minimum capital, and why no leverage (1)', '- A trade costs $2 plus 0.25% of its value (the course''s model of a cheap broker plus the currency conversion an Irish student would pay; the paper account is in dollars because the shares are). Apple''s 18 shares: $17.70 to open, $35.40 for the round trip — 0.56% of the position.
- The course''s rule: a round trip over 1% of the position is too small to trade. Carver''s principle is that costs must stay a small fraction of what the rule can earn; the course''s threshold is 1%, written in the rules table and open to revision. A $1,000 account sizing a $20 share at 30% risk would hold $400; the round trip ($6.00) is 1.5% of it: refused, with the minimum named — $2,000 for that share at that risk.
- Minimum account for Apple at today''s risk: $1,586 — the first whole number of shares worth at least the $800 the cost rule needs is three ($1,046.73), scaled by 18.18 ÷ 12. (Two shares, $697.82, would fail the 1% check: the floor is counted in whole shares, which is why it is not simply $800 × 1.515 = $1,212.) The calculator prints the minimum on every refusal. Nothing is wrong with the company; the account is too small for the share.', 215, '2026-11-12T13:40:44.802Z'),
  ('L8.11', 'docs/lessons/week-08.md', 'Lesson 8 — How Much to Bet (and the ticket that makes you write down why)', '0:50 — Costs, minimum capital, and why no leverage (2)', '- Leverage is out of scope. Leverage is what lets an account hold more than its cash: the 6% share''s $20,000 of exposure on a $10,000 account (leverage factor 2). The stop is the same distance away in price, but the loss is on twice the shares, and a broker closes a leveraged position for you at the worst price on the worst day. Apple at 18% needs no leverage at a 12% target (the rule asks for 66% of the account); the slow, steady shares are the ones that would. Carver''s book is called Leveraged Trading and spends chapters on doing it safely; this class runs the leverage-factor-1 variant — never more than the cash — and says so.', 120, '2026-11-12T13:40:44.802Z'),
  ('L8.12', 'docs/lessons/week-08.md', 'Lesson 8 — How Much to Bet (and the ticket that makes you write down why)', '1:00 — Tickets, live', 'Codes out. Each student opens `/tickets/<code>` on a laptop and, for their one instrument:
1. Reads tonight''s rule for it on `/signals`. Long → write an opening ticket, units blank (the rule''s size), journal entry: what the rule said, where the stop is, what they will do if it is hit. Flat or warming → write nothing, and say so in the journal next week; the rule opens, you don''t.
2. Reads the accepted ticket: size, fill (the latest close the toolkit holds — the decision close), cost, stop.
3. Tries one refusal on purpose: units at twice the rule''s size. Reads the sentence. That sentence is the week''s exit check (VC-20): an oversized ticket refused with arithmetic a student can follow.
Expect a third of the room to be flat and ticket-less tonight. That is the lesson, not a problem: the rule said no, and a journal line saying "the rule is flat; I wait" is a decision.', 159, '2026-11-12T13:40:44.802Z'),
  ('L8.13', 'docs/lessons/week-08.md', 'Lesson 8 — How Much to Bet (and the ticket that makes you write down why)', '1:15 — The weekly routine', 'Monday evening, every week from now until week 12, in this order: `/signals` for your instrument → your page for the stop and the stamp → the journal → (maybe) a ticket. Five minutes. The tracker runs every night after the signal pass; a close at or below the stop is stamped on your page in red with the date, and the Monday ticket closes it. Decisions on Monday from Friday''s close (or the latest the toolkit holds); fills at that close; the tutor reads process, never P&L.', 88, '2026-11-12T13:40:44.802Z'),
  ('L8.14', 'docs/lessons/week-08.md', 'Lesson 8 — How Much to Bet (and the ticket that makes you write down why)', '1:20 — Homework + close', '1. Size two more companies by hand from the signals page (any two core-tier names), check against `/size`, and bring the page.
2. The Monday routine, once, with a journal line whatever the rule says.
3. Read the Starter System''s sizing and stop-loss chapters in Leveraged Trading (course copy; the tutor''s page list). Optional: Systematic Trading ch. 9–10, where the method behind the 12% comes from (half the expected reward per unit of risk; the 12% itself is the Starter System''s figure).
Close with the sentence.', 86, '2026-11-12T13:40:44.802Z'),
  ('L9.1', 'docs/lessons/week-09.md', 'Lesson 9 — Running Your Paper Portfolio (and why drawdowns are normal)', 'Overview (1)', '90 minutes · Phase 3, week 3 of 3 · Toolkit feature: the paper account marked to market every night, the pre-trade checks (size on the account''s current value, the concentration cap, the risk budget) and the nightly per-student risk report (`/tickets/<code>`, `GET /api/risk/<code>`, the `risk` pass after the stop tracker at 23:00 UTC); small-cap tickets once an instrument has 128 closes and no unexplained jump in its series.
Methodology: Carver''s Starter System (Leveraged Trading, 2019 — the risk target and what it implies for the account''s year; running more than one instrument, with the risk shared between them) and Systematic Trading (2015, ch. 9 "Volatility targeting" — the account''s expected movement and drawdowns; ch. 11 "Portfolios" — instrument weights and the diversification multiplier, which the course sets to 1 as the conservative choice); the risk layer''s shape is the syllabus''s "PraxiRisk-derived" one — pre-trade checks, a nightly report. The course''s own numbers where the book leaves a choice are decision 20 in the syllabus. Page anchors for the two books are the tutor''s, from the course copies (OI-40).', 179, '2026-11-12T13:40:44.802Z');
INSERT INTO notes (id, source, title, heading, body, words, seeded_at) VALUES
  ('L9.2', 'docs/lessons/week-09.md', 'Lesson 9 — Running Your Paper Portfolio (and why drawdowns are normal)', 'Overview (2)', 'Week 7 gave the course when, week 8 how much. Tonight is what it is like to run it — which is mostly waiting, and mostly waiting while the account is below its last high. A rule you can hold for three weeks is a hobby; one you can hold through a 20% drawdown without touching it is a system. The toolkit''s job this week is to put the account''s true state in front of each student every night — cash, open P&L, the high-water mark, the distance below it, the risk the positions carry — in sentences that state and never instruct, so that the only thing left to decide is what to write in the journal.', 118, '2026-11-12T13:40:44.802Z'),
  ('L9.3', 'docs/lessons/week-09.md', 'Lesson 9 — Running Your Paper Portfolio (and why drawdowns are normal)', 'By the end, students can', '1. Read their own risk report and say what each line is: the account''s value at the latest closes, the high-water mark, the drawdown from it, the risk used of the 12% budget, the nearest stop.
2. Say why a drawdown is expected rather than a fault — at a 12% target the account moves about 12% a year either way, so a one-in-twenty year is around −20%, and a run of years sees deeper falls from a peak — and what the rules do about it (nothing).
3. Explain the two new refusals: concentration (one position per instrument, N instruments per account) and budget (the open positions'' risk, summed, against 12%), and why the size is now computed on the account''s current value.
4. Run the weekly routine unprompted: signal → stop → report → journal → (maybe) a ticket — and know what a small-cap ticket needs before the rule will take it.', 155, '2026-11-12T13:40:44.802Z'),
  ('L9.4', 'docs/lessons/week-09.md', 'Lesson 9 — Running Your Paper Portfolio (and why drawdowns are normal)', '0:00 — Harvest: the Monday routine, once', 'Round the room: what did the rule say for your instrument on Monday, what did you write, did you ticket? Count the room: long and holding, long and ticketed, flat and waiting, warming. Then the question that sets up the hour: "Whose account is below where it started?" Most hands. "Whose is below its own highest value?" Every hand that holds anything. That is tonight''s subject.', 66, '2026-11-12T13:40:44.802Z'),
  ('L9.5', 'docs/lessons/week-09.md', 'Lesson 9 — Running Your Paper Portfolio (and why drawdowns are normal)', '0:10 — The account marked to market: what the page now shows (1)', 'Open the test student''s page (the one enrolled for VC-20; the numbers below are its 3 Nov close). Six figures across the top, then the report in sentences:
- Account value = cash + Σ shares × the latest close the toolkit holds. The test account: $3,893.02 cash + 18 × $331.90 = $5,974.20 → $9,867.22. Not the cash (that is what is left after buying); not the capital enrolled (that was the start).
- Open P&L = (latest close − entry) × shares: (331.90 − 338.32) × 18 = −$115.56. Realised = the P&L of closed positions, net of both tickets'' costs (the test student closed on 5 Nov at $349.51: +$166.47 — (349.51 − 338.32) × 18 − 17.22 − 17.73).
- High-water mark = the highest account value the nightly report has seen, starting at the enrolled capital. Drawdown = (high − value) ÷ high: (10,000 − 9,867.22) ÷ 10,000 = 1.3%. The mark only ever rises; the drawdown is measured from it, not from the start.
- Risk used = each position''s share of the account × its instrument risk, summed: 60.55% × 19.04% = 11.5% a year of the 12% budget. This is the week-8 arithmetic run backwards on tonight''s prices.
- The nearest stop: (331.90 − 306.11) ÷ 331.90 = 7.8% below the latest close.', 221, '2026-11-12T13:40:44.802Z'),
  ('L9.6', 'docs/lessons/week-09.md', 'Lesson 9 — Running Your Paper Portfolio (and why drawdowns are normal)', '0:10 — The account marked to market: what the page now shows (2)', 'Every one of those is a line the student can check on a calculator from the page''s own numbers; the report''s sentences say the same thing in words and nothing more. Pairs: check two of the five on the test page before moving on.', 44, '2026-11-12T13:40:44.802Z'),
  ('L9.7', 'docs/lessons/week-09.md', 'Lesson 9 — Running Your Paper Portfolio (and why drawdowns are normal)', '0:25 — Drawdowns are normal (1)', 'The centre of the lesson. On the board, from the one number the course chose in week 8:
- A 12% target means a 12% year is ordinary. The account''s value moves about 12% a year either way. Half of all years end below where they started before any expected gain is counted; the rule''s expected gain is small and slow (week 7: a quarter of a unit of return per unit of risk — Carver''s figure, the course''s assumption).
- A one-in-twenty year is about −20%. 1.65 standard deviations of a 12% move is 19.8%: the account that enrols at $10,000 should expect, once in a career of such years, to see $8,000 — with the rules followed perfectly.', 120, '2026-11-12T13:40:44.802Z'),
  ('L9.8', 'docs/lessons/week-09.md', 'Lesson 9 — Running Your Paper Portfolio (and why drawdowns are normal)', '0:25 — Drawdowns are normal (2)', '- Drawdowns from a peak are deeper than years are bad, because peaks and troughs do not fall on the calendar. A run of years at a 12% target typically sees a drawdown of 20–30% from a high; one run in twenty sees 40% or more; a decade sees deeper still. (The course''s figures: a random walk at 12% a year, simulated — it ignores fat tails and the trend rule''s own shape, so take them as the floor of what to expect, not the ceiling. Carver''s own table for the Starter System is in the risk-target chapter: tutor, OI-40.) A trend rule''s drawdowns are longer than most, because it earns in a few long runs and loses a little most of the rest of the time (week 7''s "why systems beat gut feel" slide, read the other way). The sentence printed on the page is this arithmetic.
- What the rules do about a drawdown: nothing. The size was set so that the worst drawdowns are survivable; the stop closes a position, not the account; the report says how far below the high the account is and leaves the feeling to the journal. "Nothing in the rules changes because of it" is printed on the page for that reason.', 210, '2026-11-12T13:40:44.802Z'),
  ('L9.9', 'docs/lessons/week-09.md', 'Lesson 9 — Running Your Paper Portfolio (and why drawdowns are normal)', '0:25 — Drawdowns are normal (3)', '- What students do about it: write. The journal line in a drawdown — "8% below the high; the rule is still long; the stop is 6% away; I am doing nothing" — is the most valuable sentence in the course. Week 7''s flawed brain wants to act; the page''s arithmetic is the restraint.
Scripted answer — "Why not sell when it''s down 10% and buy back lower?": "Because that is a second rule, and you would have to show it works. Week 7 measured what happens when the second rule is ''how I feel tonight''. If you want the course to add a rule, write it as a rule — for everyone, next week — and we will see what it would have done." The 10% note on the page is a statement, not a threshold for action.', 139, '2026-11-12T13:40:44.802Z');
INSERT INTO notes (id, source, title, heading, body, words, seeded_at) VALUES
  ('L9.10', 'docs/lessons/week-09.md', 'Lesson 9 — Running Your Paper Portfolio (and why drawdowns are normal)', '0:40 — Two new refusals, and sizing on the current value (1)', 'Three changes to the ticket since week 8, each one sentence on the card:
- Size on the account''s current value, not the enrolled capital. The account that has fallen to $9,867.22 sizes its next position on $9,867.22; one that has risen sizes on more. This is what makes the 12% a target for the account as it is; it is also why a position opened in week 8 can be a little over or under target tonight (the page says so, and the rules do not trim it — the stop does its work).
- Instruments, N. An account runs 1 instrument unless the tutor sets more (up to 4: `npm run enrol -- --set-instruments CODE 2`). Each position is then sized at 12% ÷ N a year — 6% each for two, 4% for three, 3% for four — so the account as a whole still carries about 12%. (Carver''s full system raises the total for the diversification between instruments — the instrument diversification multiplier; the course sets it to 1: two shares that fall together on the same bad day are not the diversification the multiplier assumes. Students who have read ch. 11 will ask; say so.) Concentration: a ticket that would open position N + 1 is refused — close one first, or ask the tutor to set more instruments.', 224, '2026-11-12T13:40:44.802Z'),
  ('L9.11', 'docs/lessons/week-09.md', 'Lesson 9 — Running Your Paper Portfolio (and why drawdowns are normal)', '0:40 — Two new refusals, and sizing on the current value (2)', '- The budget. Before an opening ticket, the risk the open positions carry tonight plus the risk the new one would add must stay within 12% (+1 point of tolerance for rounding). Normally the sizing rule keeps this true by construction; it bites when instrument risk has risen since a position was opened, or when the number of instruments changed with a position open. The worked case is the test account itself: its 18 Apple shares were sized at the full 12% in week 8; if the tutor now sets it to two instruments and the student asks for Coca-Cola on the 3 Nov close ($94.08, 21.11%), the rule''s 6% size is 29 shares — and the refusal reads: "Over the risk budget: the open positions carry 11.5% a year tonight and 29 shares of KO would add 5.8% — 17.4% against the 12% target (tolerance 1 point). Fewer shares, or wait for a stop to do its work." Eleven shares would still be refused (13.7%); seven are accepted (12.9%). Every figure is pinned in `src/lib/tickets.test.ts`. The check never trims what is held — Apple stays at 18 until its stop.
The thing to say out loud: none of these three recommends anything. They say what the rule would hold, and refuse what it would not.', 216, '2026-11-12T13:40:44.802Z'),
  ('L9.12', 'docs/lessons/week-09.md', 'Lesson 9 — Running Your Paper Portfolio (and why drawdowns are normal)', '0:55 — Small caps, now', 'Since week 7 the small-cap tier''s signals have been "warming up" (fewer than 128 closes) and marked `s` as not split-adjusted. Two things changed:
- An instrument in the tier can be ticketed once it has 128 closes — the first visited reach that in early December; the signals page shows "N of 128 closes" until then, and the ticket says so.
- A series with a jump the toolkit cannot explain — a one-day move of more than 40% in the adjusted close with no row in the splits table within four days of it — is quarantined: a `Q` on the signals page with the reason, and no opening ticket until the tutor adds the row (a split, or factor 1 with a note when it was news). Mueller Industries'' two-for-one of 1 July is the tier''s first row; it is why MLI is not quarantined. Closing tickets are never gated — a stop is a stop.
Why the quarantine exists: an unexplained halving looks to the rule like a crash and to the volatility estimator like a 50% day; a position sized on that number would be a quarter of the right size, and a long opened after it would be opened on a false signal. The rule only works on prices that mean the same thing all the way along the series.', 226, '2026-11-12T13:40:44.802Z'),
  ('L9.13', 'docs/lessons/week-09.md', 'Lesson 9 — Running Your Paper Portfolio (and why drawdowns are normal)', '1:05 — The weekly routine, now with the report', 'Monday evening, in this order, five minutes: `/signals` for your instrument → your page: the stop, the stamp, the report → the journal → (maybe) a ticket. Three things about the page this week:
- The code is no longer printed on the page. The page''s address is its key: a screenshot of the page is safe to show the class; the link — and a screenshot that includes the browser''s address bar — is not. Share screenshots, not links.
- The "Nightly reports" table at the bottom is your account''s history, one row per night from the 23:00 UTC job. A flag in the last column is a statement, not an instruction, and the words are the same on the page, in this lesson and on the slides: `drawdown ≥ 10%`, `over the 12% budget`, `stop hit`, `more positions than instruments`, `no close stored`.
- The report is as of the night — the latest close the toolkit holds for any instrument; a position whose own series lags (a small cap between visits) is valued at its latest stored close and the report says so. The account strip at the top is computed when the page loads, so it can be a night ahead of the last table row.

- `/size` now takes the number of instruments too, so the calculator and your ticket agree on the 12% ÷ N size.', 232, '2026-11-12T13:40:44.802Z'),
  ('L9.14', 'docs/lessons/week-09.md', 'Lesson 9 — Running Your Paper Portfolio (and why drawdowns are normal)', '1:15 — Homework + close', '1. The Monday routine with the report, and a journal line that quotes one number from it ("the account is 2.3% below the high").
2. Check the report by hand: account value, drawdown and risk used for your own page, from the page''s own numbers; bring the arithmetic.
3. Read the Starter System''s risk-target chapter again, this time for what it says about drawdowns — and ch. 9 of Systematic Trading if you want the method. Optional: ch. 11 (why the course''s multiplier of 1 is the conservative end of Carver''s range).
4. Phase 4 begins next week: bring one question you would want to ask a tutor bot about the course, in writing.
Close with the sentence.', 118, '2026-11-12T13:40:44.802Z'),
  ('L10.1', 'docs/lessons/week-10.md', 'Lesson 10 — Ask the Tutor (and how to interrogate an AI well)', 'Overview (1)', '90 minutes · Phase 4, week 1 of 3 · Toolkit feature: the tutor bot on the course notes (`/tutor`, `POST /api/tutor` — retrieval over the lesson plans and the kit, an answer that cites the passage on every paragraph, checked like week 6''s story) and the Graham ∩ Carver watchlist (`/watchlist`, the "Graham" column on `/signals`).
Methodology: week 6''s grounding discipline (a numbered source, an answer that may say only what is on it, a check that flags what is not) applied to the course''s own notes; retrieval by full-text search (SQLite FTS5 in D1 — decision #3, spike-tested at this release) with a plain word match as the fallback. The gate reads Graham''s screens (weeks 4–5) and Carver''s rule (weeks 7–8) side by side and adds no rule of its own (syllabus, week 10; OI-68).', 137, '2026-11-12T13:40:44.802Z'),
  ('L10.2', 'docs/lessons/week-10.md', 'Lesson 10 — Ask the Tutor (and how to interrogate an AI well)', 'Overview (2)', 'Phase 3 ended with every student running a paper account by the rules. Phase 4 is the takeaway: tonight a tutor the class can question after the course ends, next week the real world''s costs, in week 12 the logins and the kit. The tutor is a consolidation device and a scam-literacy lesson in one: it answers only from the notes, it cites what it read, and it is checked — and the class''s job tonight is to catch it being wrong, because an AI that sounds sure and is wrong is the most expensive thing in finance after a tip.', 101, '2026-11-12T13:40:44.802Z'),
  ('L10.3', 'docs/lessons/week-10.md', 'Lesson 10 — Ask the Tutor (and how to interrogate an AI well)', 'By the end, students can', '1. Ask the tutor a question in the course''s own words, read the answer, and check every citation back to the passage: find the sentence, find the number.
2. Name the three ways an answer can be wrong and how the page shows each: a passage it was not given (flagged), a number that is in no passage (flagged), a tip (withheld — the passages are shown instead).
3. Say what the tutor cannot know — tonight''s prices, your account, tax, anything after the notes were written — and why a confident answer about those is wrong by construction.
4. Read the Graham ∩ Carver gate on `/watchlist` and say why it was empty on the night it was first read (6 Nov 2026), and why the account''s size decides how many names it can run (the $10,000 example).', 139, '2026-11-12T13:40:44.802Z');
INSERT INTO notes (id, source, title, heading, body, words, seeded_at) VALUES
  ('L10.4', 'docs/lessons/week-10.md', 'Lesson 10 — Ask the Tutor (and how to interrogate an AI well)', '0:00 — Harvest: the question you brought', 'Round the room, each student reads their question aloud. Sort them on the board into three columns as they come: the course can answer this ("how is the stop calculated?"), the course cannot ("what will Apple do next year?", "should I buy Coca-Cola?"), not sure. Say nothing about the sorting yet — the hour decides it.', 56, '2026-11-12T13:40:44.802Z'),
  ('L10.5', 'docs/lessons/week-10.md', 'Lesson 10 — Ask the Tutor (and how to interrogate an AI well)', '0:10 — What the tutor is, and is not (1)', 'On the projector, `/tutor`. Five sentences, each one a fact about the page:
- It has read the course''s notes and nothing else — the lesson plans (this one included; week 11''s joined the notes when it shipped), the two week-5 segments and the kit documents — the student''s sections, not the tutor''s notes — cut into about 160 passages (the page says how many and when they were indexed). Not the internet, not the news, not your account, not tonight''s prices.
- It finds passages by words, not by meaning. The question "how is the stop calculated?" becomes the words stop, calculated and the index returns the passages that use them most (stemmed: "calculated" finds "calculation"). Ask in the course''s words and it finds the course''s passages; ask in other words and it finds the wrong ones — and the model must then say the passages do not answer the question (it finds nothing only when no word of the question is in the notes).
- It answers from those passages only, and cites them on every paragraph — the `[L8.9]` tags: lesson 8, passage 9. Click one; the passage is on the page below the answer.', 198, '2026-11-12T13:40:44.802Z'),
  ('L10.6', 'docs/lessons/week-10.md', 'Lesson 10 — Ask the Tutor (and how to interrogate an AI well)', '0:10 — What the tutor is, and is not (2)', '- It is checked. A label it invented (a passage it was not given) is flagged; a number that appears in no passage it read is flagged; advice-shaped language — buy, sell, should, undervalued, a target — is caught by the same families week 6 uses, and the answer is withheld: the passages are shown, the answer is not.
- It is anonymous and rationed. No code is asked for; the question and the outcome are stored and the page lists the class''s recent questions for every visitor — so a name or a code typed into the box is published; ask about the course, not about yourself. Sixty questions a day on the course''s key, then the passages only until the budget resets.
The thing to say out loud: the citations are not decoration. They are the whole point. An answer with a citation you can check is a claim; an answer without one is a rumour.', 158, '2026-11-12T13:40:44.802Z'),
  ('L10.7', 'docs/lessons/week-10.md', 'Lesson 10 — Ask the Tutor (and how to interrogate an AI well)', '0:25 — Ask it, live', 'Three questions from the gold set first, projected, each checked by a pair: find the sentence, find the number. Then the board''s first column, three of the room''s own questions. Then — deliberately — one from the second column: "Should I buy Coca-Cola?" Watch what the page does: either the model declines (the notes say how the course decides, not what to buy) or it answers in process terms ("the rule decides; the ticket is yours") — and if it slips into a tip, the page withholds the answer and prints why. Either is the lesson: the course does not say what to buy, and neither does its tutor. Then one the notes cannot answer ("what will Apple''s shares do next year?") — the passages about Apple are retrieved (lesson 8''s worked example), and the model should say the notes carry no forecast (the rule reads the price; it does not predict it); if it slipped into one, the page would withhold it. And one made of letters that are no word at all (the record''s VC-22 used one — it is not printed here, or the notes would contain it): no passage, no call, the honest "no passage matched" — the two different ways of having nothing to say. (Until week 11 shipped, the example here was the capital-gains-tax question; the notes now carry the kit''s walkthrough, so the tutor answers it — with the Bill''s caveat.)

Pairs, five minutes: one question each, one citation each, checked. Hands up for anyone whose answer had a flag.', 257, '2026-11-12T13:40:44.802Z'),
  ('L10.8', 'docs/lessons/week-10.md', 'Lesson 10 — Ask the Tutor (and how to interrogate an AI well)', '0:40 — How to interrogate an AI well (1)', 'The lesson inside the lesson, on the board as five habits — the ones the class will keep when the AI is not this one:
1. Use the source''s words. Retrieval matches words. "Instrument risk", "the stop gap", "the 12% target", "the defensive screen", "the drawdown" — the course''s nouns find the course''s passages. (A general chatbot has the same weakness dressed better.)
2. One thing at a time. "What is the stop gap, and when does the stop move?" beats "explain stops and sizing and everything". A long question retrieves the wrong passages and the answer blends them.
3. Ask for the passage, then read it. Here the page does it for you; elsewhere, ask "where does that come from?" and refuse an answer that cannot say. A source you cannot open is not a source.
4. Check the number, not the sentence. The sentence will be fluent either way. The number is where a wrong answer shows: $31.72 is either in the passage or it is not.
5. Distrust fluency. The better the prose, the more it is worth checking — a confident wrong answer is the product that sells scams (week 6, and week 11''s second scam-literacy pass). The tutor''s flags are a training wheel; the habit is the point.', 213, '2026-11-12T13:40:44.802Z'),
  ('L10.9', 'docs/lessons/week-10.md', 'Lesson 10 — Ask the Tutor (and how to interrogate an AI well)', '0:40 — How to interrogate an AI well (2)', 'And what the tutor cannot know, said plainly: tonight''s prices and signals (ask `/signals`), your account (your page), tax and costs (week 11), anything that happened after the notes were written, and anything about you — it has no idea what you own, how much you have or what you should do. A confident answer on any of these is wrong by construction, however well put.
Scripted answer — "Why won''t it just tell me what to buy?": "Because the course doesn''t, and it only knows the course. If it ever does, the page will withhold the answer and show you the sentence that tripped the check — that''s the lesson working, not failing."', 114, '2026-11-12T13:40:44.802Z'),
  ('L10.10', 'docs/lessons/week-10.md', 'Lesson 10 — Ask the Tutor (and how to interrogate an AI well)', '0:55 — The gate: Graham ∩ Carver (1)', 'Change the page to `/watchlist`. The idea first, in one line on the board: Graham says what; Carver says when and how much. Read in that order, as a gate. A name must pass a Graham screen (the defensive seven, or the enterprising six) and be long on the rule before the course would ticket it; then the Starter System sizes it and the stop closes it. No new rule — the two the class already has, side by side; the signals page now shows each company''s Graham tests passed beside its state.
Then the first night it was read, 6 November 2026: the gate was empty. No company passed either screen (eight defensive near misses, two enterprising); every name the rule was long on — nineteen that night — failed both of Graham''s price tests, P/E ≤ 15 and P/B ≤ 1.5. Two things to say about that:
- An empty gate is a result. The rule''s answer was cash, and a journal line that says "waiting". Graham''s price bars were set in the 1970s; against a 2026 US large-cap market they say "nothing is cheap", which is a statement about the market and the bars, not a fault in the toolkit — and not a reason to loosen the bars tonight (that is a second rule; week 7''s point stands).', 222, '2026-11-12T13:40:44.802Z'),
  ('L10.11', 'docs/lessons/week-10.md', 'Lesson 10 — Ask the Tutor (and how to interrogate an AI well)', '0:55 — The gate: Graham ∩ Carver (2)', '- The account''s size decides N. A relaxed, labelled example — the Carver longs that passed the most defensive tests, sized on $10,000 — showed it: four names failed the 1% round-trip cost rule on two of them; three worked (DAL 10 shares, JNJ 5, KO 20 — 11.7% of the 12% budget used, 58% of the account in cash by design). Four instruments on $10,000 is not a bigger portfolio, it is two positions too small to trade. The example is on the board as arithmetic, not as a list: say so.
Read the page''s sentences aloud — they are statements about tonight: the gate, the near misses that are long (one Graham test short, with the failed test named), the rule''s longs that fail both screens (sorted by tests passed), and the small caps on their way to 128 closes. "A near miss is a reading list, not a pick" is printed on the page for the same reason the week-5 page says "a screen is a starting list".', 171, '2026-11-12T13:40:44.802Z');
INSERT INTO notes (id, source, title, heading, body, words, seeded_at) VALUES
  ('L10.12', 'docs/lessons/week-10.md', 'Lesson 10 — Ask the Tutor (and how to interrogate an AI well)', '1:10 — The weekly routine, with the tutor in it', 'Monday evening, five minutes, as before: `/signals` for your instrument → your page: the stop, the stamp, the report → the journal → (maybe) a ticket. Two additions: glance at `/watchlist` and write the gate''s state in one word ("empty", or the name); and if you have a question, ask the tutor before class and bring the citation you checked.', 60, '2026-11-12T13:40:44.802Z'),
  ('L10.13', 'docs/lessons/week-10.md', 'Lesson 10 — Ask the Tutor (and how to interrogate an AI well)', '1:15 — Homework + close', '1. Three questions to the tutor in the course''s words, each with one citation checked — write the passage id and whether the sentence and the number were there. If an answer carried a flag, bring it: it is the best homework in the room.
2. One question the notes cannot answer, asked anyway, and what the page did.
3. The Monday routine with the watchlist line in the journal.
4. Read the week-11 preview on the ledger: next week is the real world — a broker''s mechanics, Irish costs and tax, and the second scam-literacy pass. Bring your DeGiro questions (no accounts opened: paper only, still).
Close with the sentence.', 111, '2026-11-12T13:40:44.802Z'),
  ('L11.1', 'docs/lessons/week-11.md', 'Lesson 11 — The Real World (a broker''s mechanics, what a trade costs, what the gain is taxed at — and did you follow your rules?)', 'Overview (1)', '90 minutes · Phase 4, week 2 of 3 · Toolkit feature: explain-my-portfolio — the process review (`/tickets/<code>/review`, `GET /api/explain-my-portfolio/<code>`): every ticket and position read against the rules the student chose, by an audit that needs no AI and a reading by the course''s AI from a sheet that carries no P&L; and the costs-and-tax worksheet (`/costs`, `GET /api/costs`): the same paper trade priced in euro the way an Irish student would pay for it, the gain taxed three ways.
Methodology: the course''s grounding discipline (weeks 6 and 10) turned on the student''s own book — a numbered sheet of process facts, a reading that may say only what is on it, checks that flag what is not, and a new check for outcome language, so that "well done, it went up" cannot be said even by accident. The tax walkthrough is education: every rate with its source and its date, the Bill marked as a Bill, and nothing in it advice for anyone''s own case. Decision #22 in the syllabus.', 171, '2026-11-12T13:40:44.802Z'),
  ('L11.2', 'docs/lessons/week-11.md', 'Lesson 11 — The Real World (a broker''s mechanics, what a trade costs, what the gain is taxed at — and did you follow your rules?)', 'Overview (2)', 'Phase 4 is the takeaway. Last week the tutor; tonight the real world — what the paper account would have cost in a real one, what the gain would be taxed at, how to read a broker''s screen and a regulator''s register, and a review of eleven weeks of decisions that looks at the decisions and not at the results. The point of the evening is that the course''s process survives contact with the real world: the ticket''s cost line was a real cost, the journal entry is the record the tax form will one day need, and a rule you followed is still the thing to grade, whatever the price did.', 112, '2026-11-12T13:40:44.802Z'),
  ('L11.3', 'docs/lessons/week-11.md', 'Lesson 11 — The Real World (a broker''s mechanics, what a trade costs, what the gain is taxed at — and did you follow your rules?)', 'By the end, students can', '1. Read a broker''s fee schedule and a trade confirmation and say what the trade cost — commission, handling, conversion, spread — and compare it with the course''s model ($2 + 0.25%), using `/costs`.
2. Say how the same gain is taxed as shares, as a fund or ETF, and inside the investment account the Finance (No. 2) Bill 2026 would open — the rate, the exemption or its absence, the dates — and say which of those figures are law tonight and which are a Bill.
3. Check whether a firm is authorised on the Central Bank''s register, say what a clone firm is, and name the protection lost when dealing with an unauthorised one.
4. Read the process review of a paper account — the audit''s "not followed" lines and the AI''s reading — and check every fact tag against the sheet, as with the tutor.', 148, '2026-11-12T13:40:44.802Z'),
  ('L11.4', 'docs/lessons/week-11.md', 'Lesson 11 — The Real World (a broker''s mechanics, what a trade costs, what the gain is taxed at — and did you follow your rules?)', '0:00 — Harvest: the Monday line, and a question nobody can answer yet', 'Round the room, the Monday line from the journal: the rule''s state, the stop, the report''s sentence, the watchlist''s word. Then the question: what has your paper account cost you? Everyone has a number on their page — the ticket''s cost line — and nobody knows what it stands for. Tonight it gets a receipt. Say the frame once: the course has taught what (Graham), when and how much (Carver), and how to check (the tutor); the real world adds what it costs and what you keep. Neither changes the rules.', 91, '2026-11-12T13:40:44.802Z'),
  ('L11.5', 'docs/lessons/week-11.md', 'Lesson 11 — The Real World (a broker''s mechanics, what a trade costs, what the gain is taxed at — and did you follow your rules?)', '0:10 — A broker''s mechanics, in the course''s words (1)', 'Project the broker''s own fee page (DEGIRO''s, the broker named in week 1; any MiFID broker on an EU register works the same way and the numbers differ). Seven things to read off it, each one sentence:
- Who regulates it. DEGIRO is a branch of a German bank, supervised by BaFin, serving Ireland under the EU passport under Dutch conduct rules — it is on the German and Dutch regulators'' registers and is not supervised by the Central Bank of Ireland (the Bank''s register is where an Irish-authorised firm appears; a passported firm is checked on its home regulator''s). The habit (1:15 tonight): find the firm on a regulator''s register before the money moves, and use the register''s contact details, not the ones you were given.
- The profile. A "Basic" profile — no margin, no short selling, no derivatives — is the only one the course would recognise: the Starter System''s unleveraged variant, leverage factor 1 (week 8). The other profiles exist to lend you money; the course has said why that is out of scope.', 178, '2026-11-12T13:40:44.802Z'),
  ('L11.6', 'docs/lessons/week-11.md', 'Lesson 11 — The Real World (a broker''s mechanics, what a trade costs, what the gain is taxed at — and did you follow your rules?)', '0:10 — A broker''s mechanics, in the course''s words (2)', '- The order. Market (at best), limit (your price or better; it may not fill), stop-loss and stop-limit (triggered intraday), with a validity of a day or until cancelled. Say the course''s difference out loud: the course''s stop is a closing-price rule — read on the close, the ticket written the next day — not an order resting with the broker that fires on a wobble at 11am. Both are "stops"; they behave differently, and the journal should say which you mean.
- The currency. A euro account buying a US share converts to dollars: automatically at 0.25% each way, or by a manual conversion with a fixed fee plus the 0.25%. The dollar balance then sits in the account; the dividend arrives in dollars. The course''s paper account is in dollars because the shares are (lesson 8) — the worksheet converts the costs to euro so the room can feel them.
- The dividend. A US dividend is withheld at 30% unless the broker holds your W-8BEN, which brings it to 15% under the Ireland–US treaty — the first dividend statement tells you which you got. The rest is income (0:40).', 192, '2026-11-12T13:40:44.802Z');
INSERT INTO notes (id, source, title, heading, body, words, seeded_at) VALUES
  ('L11.7', 'docs/lessons/week-11.md', 'Lesson 11 — The Real World (a broker''s mechanics, what a trade costs, what the gain is taxed at — and did you follow your rules?)', '0:10 — A broker''s mechanics, in the course''s words (3)', '- The small print. Securities lending (the broker may lend your shares; the clause says whether and what you get), the exchange connectivity fee (€2.50 a year for a foreign exchange), the compensation scheme (German: deposits to €100,000, investments 90% to €20,000) — read as facts, not fears.
- The statement. An annual statement of transactions is raw data: buys, sells, distributions, conversions. The broker reports nothing to Revenue for you. Your record is your own — which is exactly what the ticket and the journal have been for eleven weeks.', 91, '2026-11-12T13:40:44.802Z'),
  ('L11.8', 'docs/lessons/week-11.md', 'Lesson 11 — The Real World (a broker''s mechanics, what a trade costs, what the gain is taxed at — and did you follow your rules?)', '0:25 — What the trade really costs', '`/costs` on the projector with the defaults: €10,000 into a US share for three years, sold with a 30% gain. Read the trade''s costs line by line — two orders at €2, conversion both ways (€25 and €32.50), the spread (week 2''s toll bridge, €10 at 0.1%), three years of connectivity (€7.50): €79 to open and close. Beside it the course''s own model: $2 + 0.25% a ticket, both tickets, $61.50 — the paper account''s cost line was a real cost, give or take the conversion. Then the ETF column: €1 an order on a euro venue, no conversion, and the annual charge taken inside the price (0.2% a year, €69 over the holding — the cost you never see on a statement). The sentence to land: the trade costs tens of euro; the holding costs tens a year; the tax, in a minute, costs hundreds. Change the inputs live — a €2,000 trade, a 1% spread on a small cap (week 2''s surprise) — and watch the order change.', 170, '2026-11-12T13:40:44.802Z'),
  ('L11.9', 'docs/lessons/week-11.md', 'Lesson 11 — The Real World (a broker''s mechanics, what a trade costs, what the gain is taxed at — and did you follow your rules?)', '0:40 — Irish tax, the walkthrough (1)', 'Three regimes, the kit page in every pair''s hands, the worksheet''s three cards on the projector. Every figure with its source and its date; the Bill marked as a Bill.
- Shares, outside any account — capital gains tax. 31% of the gain, for disposals on or after 7 October 2026 (Budget 2027; 33% before). The first €1,270 of a year''s gains is exempt. A loss on shares offsets a gain on shares and carries forward (the four-week rule: a loss on shares bought back within four weeks is restricted). Pay by 15 December for disposals from January to November, by 31 January for December''s; the return — CG1, or Form 11 / Form 12 — by 31 October of the following year. The worksheet: €3,000 gain → €1,730 taxable → €536.30.', 132, '2026-11-12T13:40:44.802Z'),
  ('L11.10', 'docs/lessons/week-11.md', 'Lesson 11 — The Real World (a broker''s mechanics, what a trade costs, what the gain is taxed at — and did you follow your rules?)', '0:40 — Irish tax, the walkthrough (2)', '- A fund or ETF, outside any account — the exit tax. 38% of the gain or distribution in 2026 (41% to the end of 2025; Budget 2026 cut it), 35% from 1 January 2027 as announced in Budget 2027 and drafted in the Bill. No exemption; a loss on one fund cannot be set against anything; a deemed disposal every eight years taxes the gain as if sold (credited at the real sale). The worksheet: €1,050 on the same €3,000, €1,140 if sold this year. Self-assessed on Form 11 / Form 12 — the broker''s statement is raw data.', 100, '2026-11-12T13:40:44.802Z'),
  ('L11.11', 'docs/lessons/week-11.md', 'Lesson 11 — The Real World (a broker''s mechanics, what a trade costs, what the gain is taxed at — and did you follow your rules?)', '0:40 — Irish tax, the walkthrough (3)', '- Inside the Individual Investment Account — the Bill''s name; "Personal Investment Account" in the Budget speech. From 1 July 2027 on a commencement order: 18 or over, resident, one account; €12,000 a year in; nothing inside — no CGT, no dividend withholding, no exit tax, no deemed disposal — and instead 1% a year on the average daily value above €50,000, calculated by the provider each 31 December and deducted from the account (a charge on value: payable in a losing year too). The worksheet: €0 on a €10,000 trade; €570 over three years on a €60,000 one. Two things the Bill as published does not settle, and the room should hear it: whether a share listed only in the US qualifies, and how US withholding is treated inside. Both are for the Act and Revenue''s guidance.
- Dividends are income: US dividends withheld at 15% (with the W-8BEN) and then taxed at your marginal rate with USC and PRSI, with credit for the 15%; an Irish company''s dividend has 25% withholding tax taken and credited. The worksheet shows the withholding and stops there — the rest depends on the person.
- Stamp duty: 1% buying shares in an Irish company, 0.5% UK, none on US shares or Irish-domiciled ETFs — at purchase, on the worksheet''s Irish column.', 219, '2026-11-12T13:40:44.802Z'),
  ('L11.12', 'docs/lessons/week-11.md', 'Lesson 11 — The Real World (a broker''s mechanics, what a trade costs, what the gain is taxed at — and did you follow your rules?)', '0:40 — Irish tax, the walkthrough (4)', '- The discipline. The Bill was published on 19 October 2026; it is expected to be an Act in December; the account needs a commencement order. The page says "as checked on 12 November 2026" and marks every line that depends on the Bill. Before anyone acts on a figure, it is re-checked against the Finance Act and Revenue''s guidance — the course models the check, it does not give the advice. Record-keeping closes the segment: date, quantity, price, the conversion rate, the cost line, for every buy and sell — the ticket has had all of them since week 8; a journal is a tax record with a reason attached.', 111, '2026-11-12T13:40:44.802Z'),
  ('L11.13', 'docs/lessons/week-11.md', 'Lesson 11 — The Real World (a broker''s mechanics, what a trade costs, what the gain is taxed at — and did you follow your rules?)', '1:00 — Explain my portfolio: did you follow your rules? (1)', 'The test account''s review page on the projector. Two parts, in order:
- The audit — the rules applied to the rows, no AI: Not followed (a stop hit and the position still open more than a trading week later; a close with the stop not hit; a close later than the week''s routine), Followed (the stop answered within the week; the position opened with the rule long), Journal (word tests — the entry names no rule, no stop; said as word tests), The report (the flags, counted — and a drawdown is not a breach). Read the test account''s lines aloud.', 102, '2026-11-12T13:40:44.802Z'),
  ('L11.14', 'docs/lessons/week-11.md', 'Lesson 11 — The Real World (a broker''s mechanics, what a trade costs, what the gain is taxed at — and did you follow your rules?)', '1:00 — Explain my portfolio: did you follow your rules? (2)', '- The reading — press the button: the course''s AI writes two or three paragraphs from a numbered sheet of process facts only: tickets, dates, the rule''s state, whether the stop was hit, the journal''s words, the flags. The sheet carries none of the toolkit''s profit, loss, account-value or drawdown figures and no price level beyond the entry — open "The sheet the AI reads" under the page and show the room there is no P&L on it. It cannot praise what it cannot see. Say the one thing it can see: your own journal words — if an entry says "made €500", that is on the sheet as you wrote it; the AI is told to quote entries in fragments only and to repeat no result words, and the net is partial by nature. Then the checks: a fact tag not on the sheet, a paragraph that cites nothing, a number from nowhere, a tip, and — new tonight — outcome language ("well done", "profit", "it went up", "lucky") — any one of them and the reading is withheld, the audit standing on its own. The page says why.', 190, '2026-11-12T13:40:44.802Z');
INSERT INTO notes (id, source, title, heading, body, words, seeded_at) VALUES
  ('L11.15', 'docs/lessons/week-11.md', 'Lesson 11 — The Real World (a broker''s mechanics, what a trade costs, what the gain is taxed at — and did you follow your rules?)', '1:00 — Explain my portfolio: did you follow your rules? (3)', '- The exercise, pairs, five minutes: the printed fixture from the suite — three positions, one profitable close with the stop not hit. What does the audit say about KO? (Not followed: closed with the stop not hit; the journal says "nervous".) What would a reading that praised the profit be? (Withheld.) The syllabus''s exit check for the week is exactly this: a deliberately rule-breaking test book is reviewed and the breach is flagged, not the P&L — pinned in `src/lib/review.test.ts`, shown live on the test account (VC-23).
- The habit. Monday evening, five minutes, as before — with the review page once a week. Three readings a day per account, the class''s budget on the course''s key; the audit is free and always there (the page and the API''s plain address show it with no AI call; only the button, or `?ai=1` on the API, asks for a reading — so a link pasted into a chat spends nothing). The button lands you back on the page with the reading: a refresh never spends a second one.', 178, '2026-11-12T13:40:44.802Z'),
  ('L11.16', 'docs/lessons/week-11.md', 'Lesson 11 — The Real World (a broker''s mechanics, what a trade costs, what the gain is taxed at — and did you follow your rules?)', '1:15 — Scam literacy II: platforms', 'Week 6 was stories versus numbers; tonight is the platform itself. The Central Bank''s register on the projector: type a firm''s name; read the entry; call the number on the register, not the number on the website. A clone firm copies a real firm''s name, address and authorisation number and changes only the bank account — the Bank publishes a warning most weeks; read tonight''s. Then the list, one breath each, the kit page in their hands: an unregistered or "offshore-regulated" platform; guaranteed or "fixed" returns; pressure and a deadline; a celebrity or an ad that found you; remote-access software "to help you set up"; a fee to withdraw; a second firm that will "recover your losses" for a fee; crypto or forex "platforms" with a dashboard that only ever goes up. What you lose with an unauthorised firm: the Investor Compensation Scheme and the Financial Services and Pensions Ombudsman — both exist only for authorised firms. Report to the Bank: (01) 224 5800, centralbank.ie/financialscams (both as printed on the Bank''s own warning notices — checked at the build; check again before printing). The link to week 10: the confident wrong answer and the confident wrong platform sell the same way — fluency. The defence is the same: find the register entry, find the number, check it yourself.', 218, '2026-11-12T13:40:44.802Z'),
  ('L11.17', 'docs/lessons/week-11.md', 'Lesson 11 — The Real World (a broker''s mechanics, what a trade costs, what the gain is taxed at — and did you follow your rules?)', '1:25 — Homework + close', '1. Price your own book. Run `/costs` with your largest paper trade''s size and its gain or loss to date; write the three tax figures in the journal, with the date you checked them and the line "Bill, not law" where it applies.
2. Ask for a reading of your account and check two fact tags against the sheet; bring one flag if you got one.
3. The register check, written into the journal as a rule: before any money moves, the firm on a register, the number from the register.
4. Demo day: choose the one decision from your journal you will present next week — judged on process, not on what the price did. Bring the entry, before and after.
Close with the sentence.', 126, '2026-11-12T13:40:44.802Z'),
  ('K-RULES.1', 'kit/starter-system-rules-card.md', 'The Starter System — the rules card', 'Overview', 'Takeaway kit · Intro to the Stock Market · Phase 3 (weeks 7–9)
One instrument, one opening rule, one closing rule, one sizing formula, one weekly routine. Robert Carver''s Starter System (Leveraged Trading, 2019), run by the course on ordinary US shares with no leverage, in a paper account. The toolkit runs exactly these rules from one table (`src/lib/signals.ts`, `src/lib/sizing.ts`); the card and the site cannot disagree. Where the book leaves a choice, the course''s number is marked (course) — decisions 17–20 in the syllabus.', 85, '2026-11-12T13:40:44.802Z'),
  ('K-RULES.2', 'kit/starter-system-rules-card.md', 'The Starter System — the rules card', '1 · The opening rule — when', '- Two averages of the adjusted close: 16-day and 64-day exponentially weighted (λ = 2/17 and 2/65).
- Forecast = 3.75 × (fast − slow) ÷ σ of daily price changes (35-day), capped at ±20.
- LONG when the forecast is above zero; FLAT otherwise. No shorts. The rule opens; you don''t.
- The rule needs 128 closes before it is trusted ("warming up" on the signals page).', 68, '2026-11-12T13:40:44.802Z'),
  ('K-RULES.3', 'kit/starter-system-rules-card.md', 'The Starter System — the rules card', '2 · The risk target — how much the account should move', '- 12% a year — the account''s volatility, not a return. Carver''s number for the Starter System.
- A share that moves 24% a year gets half the account; one that moves 6% gets all of it and the account accepts 6% (no leverage: exposure never exceeds the account).
- It is a budget for the whole account. An account runs N instruments (1 unless the tutor sets more, up to 4); each position is sized at 12% ÷ N a year — 6% each for two, 4% for three, 3% for four — so the account as a whole still carries about 12% (course: Carver''s diversification multiplier set to 1).
- What 12% means for your year: the account moves about 12% either way; a one-in-twenty year is about −20%; a run of years typically sees a drawdown of 20–30% from a high, one run in twenty 40% or more, and a decade deeper still. The size was set so that those are survivable. Nothing in the rules changes because of a drawdown.', 174, '2026-11-12T13:40:44.802Z'),
  ('K-RULES.4', 'kit/starter-system-rules-card.md', 'The Starter System — the rules card', '3 · Position sizing — how many (1)', '```
target exposure = account value × (12 ÷ N) ÷ instrument risk      (capped at the account)
units           = whole shares that fit in it
```
- Account value = cash + the open positions at the latest close the toolkit holds — the account as it is tonight, not the capital enrolled (from week 9).
- Instrument risk = the share''s annualised volatility (the signals page): σ of daily % returns × 16.
- Example (N = 1): a $10,000 account, Apple at $348.91, instrument risk 18.18% → $6,600.66 → 18 shares ($6,280.38; 62.8% of the account; carrying 11.42% a year). With N = 2 the same account holds 9 ($3,300.33 → 9 shares, 5.71% a year) and has room for a second name.
- You may hold fewer shares than the rule''s size, never more. The size does not change with the forecast''s strength — a fixed position while the rule is on (Carver''s full system scales it by the forecast; not in the course).', 167, '2026-11-12T13:40:44.802Z'),
  ('K-RULES.5', 'kit/starter-system-rules-card.md', 'The Starter System — the rules card', '3 · Position sizing — how many (2)', '- The budget check: before an opening ticket, the risk the open positions carry tonight plus the new position''s must stay within 12% (one point of tolerance). It stops you adding risk; it never trims what you hold — the stop does that. Worked case (3 Nov 2026 closes): 18 Apple shares sized at the full 12% in week 8 carry 11.5%; with the account set to two instruments, Coca-Cola''s 6% size of 29 shares would add 5.8% → refused; 7 shares (+1.4%) are accepted.
- The calculator, `/size`, takes the number of instruments, so it and the ticket size the same way.', 103, '2026-11-12T13:40:44.802Z');
INSERT INTO notes (id, source, title, heading, body, words, seeded_at) VALUES
  ('K-RULES.6', 'kit/starter-system-rules-card.md', 'The Starter System — the rules card', '4 · The closing rule — the stop', '```
stop gap   = ½ × instrument risk × entry price        (fixed on the day you enter)
stop level = highest close since entry − stop gap     (only ever rises)
```
- A close at or below the stop closes the position: at the next decision, with a ticket and a journal line. The tracker stamps it in red on your page the night it happens.
- The rule''s flip to FLAT does not close a position; the stop does.
- After a close — the stop''s or your own — no re-entry on the same signal: the rule must go flat and then long again (a fresh crossover on or after the day you closed) first (course).
- Example: Apple entered at $348.91 → gap $31.72 → first stop $317.19; after a $360 close the stop is $328.28.', 139, '2026-11-12T13:40:44.802Z'),
  ('K-RULES.7', 'kit/starter-system-rules-card.md', 'The Starter System — the rules card', '5 · Costs and the smallest account (course)', '- A trade costs $2 + 0.25% of its value (a cheap broker plus the currency conversion). The paper account is in dollars, the shares'' currency.
- A position whose round trip costs more than 1% of it is too small to trade: the calculator refuses and names the minimum account — counted in whole shares (Apple at 18.18% risk and $348.91: three shares must fit, so $1,586). Nothing is wrong with the company; the account is too small for the share.
- Whole shares only. Cash equities only. Long only. Leverage factor 1.', 94, '2026-11-12T13:40:44.802Z'),
  ('K-RULES.8', 'kit/starter-system-rules-card.md', 'The Starter System — the rules card', '6 · The weekly routine — Monday evening, five minutes', '1. `/signals` — the rule for your instrument on the latest close.
2. Your page, `/tickets/<code>` — the stop, the distance to it, the stamp if it was hit; the risk report: the account''s value, the high-water mark and the drawdown from it, the risk used of the 12% budget, the nearest stop. The nightly rows at the bottom are your history; a flag there is a statement, not an instruction.
3. The journal — what the rule said, what you will do, why, quoting one number from the report. Every week, even when the answer is "nothing".
4. (Maybe) a ticket — open at the rule''s size when the rule is long and you have an instrument free; close the whole position when the stop was hit. Fills at the latest close the toolkit holds (the decision close).
The page''s address is its key: share a screenshot of the page, never the link — and not a screenshot with the browser''s address bar in it.', 166, '2026-11-12T13:40:44.802Z'),
  ('K-RULES.9', 'kit/starter-system-rules-card.md', 'The Starter System — the rules card', '7 · What the ticket will refuse, and why (1)', 'It says — Because
"The rule opens, you don''t" — the rule is FLAT or warming up for that share tonight
"Oversized" — you asked for more than the rule''s size — with the arithmetic
"You already hold …" — one position per instrument
"Wait for a fresh crossover" — the rule has been long since before your last close
"Not enough cash" — open positions and their costs come first
"Concentration" — your account runs N instruments and N positions are open — close one first, or ask the tutor to set more
"Over the risk budget" — tonight''s risk of the open positions plus the new one''s would pass 12% (a share got wilder since entry, or N was lowered)
"The journal entry is the ticket" — a blank reason is not a decision
"Needs a paper account of at least …" — one share must fit and the round trip must clear 1%
"… its rule is still warming up (N closes stored of the 128 …)" — a small-cap instrument needs 128 closes before it can be ticketed
"… is quarantined: the adjusted close moved ×… with no splits row to explain it" — a jump in a small-cap series the toolkit cannot explain — no opening ticket until the tutor adds the splits row (a split, or factor 1 for news); a `Q` on the signals page', 232, '2026-11-12T13:40:44.802Z'),
  ('K-RULES.10', 'kit/starter-system-rules-card.md', 'The Starter System — the rules card', '7 · What the ticket will refuse, and why (2)', 'Closing tickets are never refused for N, the budget or the tier: a stop is a stop.
We grade decisions, not outcomes. Education, not advice: a size is what a rule would hold in a paper account; nothing on this card is a recommendation to buy or sell anything.', 49, '2026-11-12T13:40:44.802Z'),
  ('K-START.1', 'kit/student-quickstart.md', 'Student Quickstart', 'Overview', 'Takeaway kit · Intro to the Stock Market', 8, '2026-11-12T13:40:44.802Z'),
  ('K-START.2', 'kit/student-quickstart.md', 'Student Quickstart', 'What you need for this course', '1. A browser. Phone, tablet or laptop — all fine.
2. The course web address, written on the whiteboard each week.
3. Your decision journal (printed) and a pen.
That''s the entire kit list. You will never be asked to install anything.', 42, '2026-11-12T13:40:44.802Z'),
  ('K-START.3', 'kit/student-quickstart.md', 'Student Quickstart', 'Each week', 'Open the course address. The site grows a new capability every week, in step with the lesson — week 1 is one page and one button; by week 9 you''ll have a paper portfolio, a value screener and a risk report sitting there; from week 10 a tutor you can question; from week 11 a review of your own process and a worksheet of what the real world charges. Nothing you do on it costs money or touches a real market. Paper portfolios only, all twelve weeks.', 87, '2026-11-12T13:40:44.802Z');
INSERT INTO notes (id, source, title, heading, body, words, seeded_at) VALUES
  ('K-START.4', 'kit/student-quickstart.md', 'Student Quickstart', 'Ask the tutor (from week 10)', '`/tutor` on the course address. It has read the course''s notes — the lesson plans and this kit — and nothing else: not the internet, not the news, not your account. Ask in the course''s words ("how is the stop calculated?", "what is a drawdown?"), read the answer, and check the citations: every paragraph names the passages it rests on, and the passages are on the page below the answer — find the sentence, find the number. A number that is in no passage is flagged; a tip is withheld (the course does not say what to buy, and neither does its tutor). It cannot see your account or tonight''s prices — your page and `/signals` have those. No code is asked for; the class can see what was asked, not who asked.
`/watchlist` is the two rules read side by side: Graham''s screens (what) and Carver''s rule (when, how much) as a gate. Most nights it says "nothing" — an empty gate is a result, and "waiting" is a decision worth a journal line.', 175, '2026-11-12T13:40:44.802Z'),
  ('K-START.5', 'kit/student-quickstart.md', 'Student Quickstart', 'Did you follow your rules? (from week 11)', 'On your own page, "review my process": every ticket and position read against the rules you chose. The audit needs no AI — a stop hit and the position still open, a close with the stop not hit, a journal entry that names no rule — and is always there. The reading is written by the course''s AI from a sheet of process facts that carries no profit, loss or account value, so it can only talk about process; a reading that praises a result, invents a number, cites a fact that is not there, or tips is withheld, and the page says why. Three readings a day per account; the button lands you back on the page with the reading. Check the fact tags, as with the tutor — the sheet carries your own journal words as you wrote them, so a result you wrote yourself is the one thing it can see.
`/costs` is the worksheet from lesson 11: what a trade really costs through a broker, in euro, and the same gain taxed three ways — as shares, as a fund or ETF, and inside the investment account the Finance Bill would open in July 2027 — every rate with its date, the Bill marked as a Bill. The kit''s walkthrough (`costs-and-tax-walkthrough.md`) and the scam-spotting notes go with it.', 222, '2026-11-12T13:40:44.802Z'),
  ('K-START.6', 'kit/student-quickstart.md', 'Student Quickstart', 'Wait — don''t I need to set up the software?', 'No. Your tutor builds the toolkit; you use it. Building it is a separate craft that happens off-stage so that class time stays on the actual subject: how to make good investment decisions and how to avoid being parted from your money.', 42, '2026-11-12T13:40:44.802Z'),
  ('K-START.7', 'kit/student-quickstart.md', 'Student Quickstart', 'Then why is the code public?', 'Because this course tells you that opacity is where the fee-takers and the scammers live, and it would be poor form to then ask you to trust a black box. Every line of the toolkit — every rule in the screener, every number in the risk calculation — is readable by anyone, forever, at the repository address in your kit. You don''t need a GitHub account to read it. Click the link, browse the files, same as any web page.
If you''re curious enough to want to run it yourself, say so and your tutor will point you at the builder''s guide. It''s genuinely optional, and it is not part of the course.', 113, '2026-11-12T13:40:44.802Z'),
  ('K-START.8', 'kit/student-quickstart.md', 'Student Quickstart', 'The three promises, so you can hold us to them', '- Paper portfolios only. Nobody risks a cent in this room.
- No tips, ever. You leave with a process, not a portfolio.
- Everything is open. Every tool we use is built in public.
Education, not advice. Nothing in this course is a recommendation to buy or sell anything.', 50, '2026-11-12T13:40:44.802Z'),
  ('K-JOURNAL.1', 'kit/decision-journal.md', 'The Decision Journal', 'Overview', 'Takeaway kit · page 1 · Intro to the Stock Market
The one rule of this course that is never waived: no entry, no trade. Every paper trade gets a journal entry before execution. The journal is how we grade decisions instead of outcomes — because six months later, without it, your memory will quietly rewrite history in your favour. Everyone''s does.', 62, '2026-11-12T13:40:44.802Z'),
  ('K-JOURNAL.2', 'kit/decision-journal.md', 'The Decision Journal', 'Before the decision', 'Field — Your entry
Date & time
The decision, in one sentence
What rule or signal triggered this? (gut feeling is an answer — write it down honestly)
My thesis: why this, why now, in two sentences max
What would prove me wrong? (be specific — a price, a fact, a date)
Size, and why that size (per the course rules once you have them)
One number from tonight''s report (from week 9: how far below the high the account is, or the risk it carries — e.g. "2.3% below the high")
How calm am I right now? (1 = fully calm … 5 = excited or anxious)
Review date (when will I judge this?)', 115, '2026-11-12T13:40:44.802Z'),
  ('K-JOURNAL.3', 'kit/decision-journal.md', 'The Decision Journal', 'At the review date', 'Field — Your entry
Date
What actually happened
Did I follow my own rules? (yes / no — no partial credit)
Grade the process: what would I repeat? What would I change?
Was the outcome mostly luck or mostly skill — and how do I know?', 46, '2026-11-12T13:40:44.802Z');
INSERT INTO notes (id, source, title, heading, body, words, seeded_at) VALUES
  ('K-JOURNAL.4', 'kit/decision-journal.md', 'The Decision Journal', 'A worked example (everyday version, from lesson 1)', 'Before — Date: Tue 8 Sep, 7:05pm. Decision: Take the back road home instead of the N25. Trigger: Radio said roadworks at the viaduct. Thesis: Roadworks at rush hour usually cost me 20+ minutes; the back road is slower but steady. Proves me wrong: If the back road takes over 45 minutes, the detour wasn''t worth it. Size: n/a — but note I''m risking 10 known minutes to avoid 20 uncertain ones. Calm: 2. Review: On arrival.
After — Took 38 minutes; a neighbour on the N25 took 31 — the roadworks had lifted. Followed my rules? Yes. Process grade: Good decision with the information I had at 7:05; I''d repeat it. Checking a live traffic app first would improve the process. Luck or skill? The outcome (losing 7 minutes) was luck — the roadworks happened to lift. The decision stands.
Notice what the journal just did: it let you lose and still be right. That is the entire course, in one car journey.
Print a stack. Paper beats apps for this — no edit button, no delete.
Education, not advice — nothing in this kit is a recommendation to buy or sell anything.', 194, '2026-11-12T13:40:44.802Z'),
  ('K-READING.1', 'kit/reading-list.md', 'Reading List (seeded week 1 — grows with the course)', 'Overview', 'Takeaway kit · Intro to the Stock Market
Nothing here is required in week 1. Assigned chapters are announced in the week they matter; everything else is for curiosity. Your library can source most of these — the good ideas in investing are old enough to be free.', 48, '2026-11-12T13:40:44.802Z'),
  ('K-READING.2', 'kit/reading-list.md', 'Reading List (seeded week 1 — grows with the course)', 'The two books the course is built on', '- Benjamin Graham, The Intelligent Investor — chapters 8 (Mr. Market), 14 (stock selection for the defensive investor) and 20 (margin of safety), assigned across weeks 4–6. The rest is optional; those three chapters are the value half of this course, and chapter 14 is where our screener''s criteria actually come from.
- Benjamin Graham & David Dodd, Security Analysis — the professional companion, and the older, heavier book (1934). Not assigned: nobody needs 700 pages of Depression-era prose to pass this course. But it is where the reasoning beneath the checklist lives — why book value matters, why earnings must be examined over a full cycle, what a margin of safety is actually protecting you from. Recommended for anyone who finishes week 5 wanting to argue with the criteria rather than just apply them.
- Robert Carver, Leveraged Trading — the Starter System chapters, assigned across weeks 7–9. We use his rules on ordinary shares with no leverage; the system''s discipline is the point, not the leverage.', 168, '2026-11-12T13:40:44.802Z'),
  ('K-READING.3', 'kit/reading-list.md', 'Reading List (seeded week 1 — grows with the course)', 'Rules, the Carver way (Phase 3, weeks 7–9) (1)', '- Robert Carver, Systematic Trading (2015) — the fuller book behind the Starter System: chapter 1 on the flawed human brain, chapter 3 on fooling yourself by fitting rules to the past, chapter 7 on forecasts (the rule the toolkit runs, and why the scalar is 3.75), chapters 9–10 on volatility targeting and position sizing (where the method behind week 8''s 12% comes from (half the expected reward per unit of risk; the figure itself is the Starter System''s)). Optional; the tutor''s course copy is this one.
- The Starter System rules card — `kit/starter-system-rules-card.md`: the opening rule, the risk target, the sizing formula, the stop, the costs and the weekly routine on one page, with the course''s own numbers marked.
- pysystemtrade — Carver''s own open-source trading system (github.com/robcarver17/pysystemtrade, GPL). The toolkit''s constants were checked against it; you can read the same rule in his hand. For the curious, not required.
- Brad Barber & Terrance Odean, "Trading Is Hazardous to Your Wealth" — Journal of Finance 55(2), 2000. The 66,000-household study behind week 7''s first slide. Free versions on the authors'' pages.
- Terrance Odean, "Are Investors Reluctant to Realize Their Losses?" — Journal of Finance 53(5), 1998. The disposition effect, measured.', 204, '2026-11-12T13:40:44.802Z'),
  ('K-READING.4', 'kit/reading-list.md', 'Reading List (seeded week 1 — grows with the course)', 'Rules, the Carver way (Phase 3, weeks 7–9) (2)', '- Brian Hurst, Yao Hua Ooi & Lasse Pedersen, "A Century of Evidence on Trend-Following Investing" — Journal of Portfolio Management 44(1), 2017. Trend rules like ours, 1880–2016, 67 markets: modest returns, long drawdowns. Free on AQR''s site. The honest answer to "does this actually make money?".', 47, '2026-11-12T13:40:44.802Z'),
  ('K-READING.5', 'kit/reading-list.md', 'Reading List (seeded week 1 — grows with the course)', 'On luck, skill, and judging decisions (the week-1 theme)', '- Annie Duke, Thinking in Bets — where "resulting" comes from; short and readable.
- Michael Mauboussin, The Success Equation — the luck–skill continuum, properly worked out.
- Morgan Housel, The Psychology of Money — behaviour beats spreadsheets; the friendliest book on this list.', 44, '2026-11-12T13:40:44.802Z'),
  ('K-READING.6', 'kit/reading-list.md', 'Reading List (seeded week 1 — grows with the course)', 'Sensible general grounding', '- John Kay, The Long and the Short of It — investing for "people who are not in the industry," UK/Ireland-flavoured and refreshingly unexcitable.', 24, '2026-11-12T13:40:44.802Z'),
  ('K-READING.7', 'kit/reading-list.md', 'Reading List (seeded week 1 — grows with the course)', 'The weekly press habit (optional but recommended)', '- Investors'' Chronicle — weekly, aimed at private investors; it still runs quantitative stock screens, including Graham-style ones, which will look very familiar by week 5. (investorschronicle.co.uk)
- The Financial Times and The Economist — for the world the companies live in. Paywalled; many Irish libraries carry both in print or via their digital services — ask at the desk before subscribing to anything.', 64, '2026-11-12T13:40:44.802Z');
INSERT INTO notes (id, source, title, heading, body, words, seeded_at) VALUES
  ('K-READING.8', 'kit/reading-list.md', 'Reading List (seeded week 1 — grows with the course)', 'Free lectures', '- LSE public events — the London School of Economics runs free public lectures, streamed and archived as video and podcast (lse.ac.uk/events). One curated event per phase is part of the course; the term calendar and podcast feed links will be added here when published.', 45, '2026-11-12T13:40:44.802Z'),
  ('K-READING.9', 'kit/reading-list.md', 'Reading List (seeded week 1 — grows with the course)', 'Scam literacy (weeks 6 and 11, but bookmark now)', '- CCPC — the Competition and Consumer Protection Commission''s scam guidance (ccpc.ie).
- Central Bank of Ireland — check any firm against the register, and read the warnings list, before money moves (centralbank.ie).
Living document — items are added in the week they''re taught. Suggestions welcome; tips are not.
Education, not advice — nothing in this kit is a recommendation to buy or sell anything.', 65, '2026-11-12T13:40:44.802Z'),
  ('K-COSTS.1', 'kit/costs-and-tax-walkthrough.md', 'Costs and tax — the walkthrough', 'Overview', 'Takeaway kit · Intro to the Stock Market · written for lesson 11, as checked on 12 November 2026
What a trade costs through a broker, and what the gain is taxed at in Ireland — the figures as published on the dates given, with the Bill marked as a Bill. This page is education: it says what the published rules would charge on a paper trade. It is not tax advice, and your own case is a question for Revenue''s guidance or a tax adviser. The toolkit''s worksheet (`/costs`) does the arithmetic on any numbers you give it.', 99, '2026-11-12T13:40:44.802Z'),
  ('K-COSTS.2', 'kit/costs-and-tax-walkthrough.md', 'Costs and tax — the walkthrough', '1 · Before any money moves', '- Find the firm on a regulator''s register. An Irish-authorised firm is on the Central Bank of Ireland''s register (registers.centralbank.ie — "Check if a firm is regulated"); a firm serving Ireland from another EU country under the passport is on its home regulator''s register (DEGIRO: BaFin in Germany, with a Dutch branch under the AFM). A firm on no register is not a broker.
- Use the register''s contact details, not the ones on the website or in the message that found you. A clone firm copies a real firm''s name, address and authorisation number and changes only the bank account.
- The profile. A basic account — no margin, no short selling, no derivatives — is the only kind the course recognises: the Starter System''s unleveraged variant.
- The forms. A W-8BEN (the US tax form a non-US investor signs through the broker) brings the withholding on US dividends from 30% to 15% under the Ireland–US treaty; the first dividend statement shows which rate you got.
- The small print. Securities lending (may the broker lend your shares, and for what?); the compensation scheme (which country''s, and how much — DEGIRO''s is German: deposits to €100,000, investments 90% to €20,000); the connectivity fee for a foreign exchange.', 208, '2026-11-12T13:40:44.802Z'),
  ('K-COSTS.3', 'kit/costs-and-tax-walkthrough.md', 'Costs and tax — the walkthrough', '2 · An order, in the course''s words', 'The order — What it does — The course''s note
Market ("at best") — fills now at the price on offer — you pay the spread to cross — week 2''s toll bridge
Limit — fills at your price or better, or not at all — the ticket''s price is the close; a limit order the next morning is the real-world version
Stop-loss / stop-limit — rests with the broker and fires intraday when the price touches it — not the course''s stop: Carver''s is a closing-price rule, read on the close, the ticket written the next day; a resting order fires on a wobble at 11am
Day / good-till-cancelled — how long the order waits — write the validity in the journal', 123, '2026-11-12T13:40:44.802Z'),
  ('K-COSTS.4', 'kit/costs-and-tax-walkthrough.md', 'Costs and tax — the walkthrough', '3 · What a trade costs', 'The worksheet''s defaults — €10,000 into a US share through a euro account, sold three years later with a 30% gain — on a published Irish schedule (DEGIRO, autumn 2026; confirm on the broker''s site):
Line — Euro — Where it comes from
Commission and handling, buy — 2.00 — €1 + €1 an order
Commission and handling, sell — 2.00
Currency conversion, buy — 25.00 — 0.25% of €10,000 (Auto FX; a manual conversion is a fixed fee plus 0.25%)
Currency conversion, sell — 32.50 — 0.25% of the €13,000 sale
The spread — 10.00 — 0.1% of the value for a large cap — a small cap''s can be ten times that
Exchange connectivity — 7.50 — €2.50 a year for a foreign exchange, three years
To open and close — 79.00 — the course''s model ($2 + 0.25% a ticket, both tickets) says $61.50
A euro-listed UCITS ETF in a broker''s core selection: €1 an order, no conversion, no stamp duty — and an annual charge (TER) taken inside the price: 0.2% a year is €69 over the three years on the average value, the cost you never see on a statement.
Stamp duty on buying shares: 1% for an Irish-registered company, 0.5% for a UK one, none on US shares or Irish-domiciled ETFs.

The sentence: the trade costs tens of euro; the holding costs tens a year; the tax costs hundreds.', 235, '2026-11-12T13:40:44.802Z'),
  ('K-COSTS.5', 'kit/costs-and-tax-walkthrough.md', 'Costs and tax — the walkthrough', '4 · The same gain taxed three ways (1)', 'The worksheet''s €3,000 gain (€10,000 → €13,000 over three years):
Shares, outside any account — A fund or ETF, outside — Inside the Individual Investment Account
The tax — Capital gains tax — The exit tax — A 1% charge on value
The rate — 31% for disposals on or after 7 Oct 2026 (33% before) — Budget 2027; the Bill — 38% in 2026; 35% from 1 Jan 2027 (41% to the end of 2025) — the Bill — 1% a year on the average daily value above €50,000; nothing below it — the Bill
Exemption — the first €1,270 of a year''s gains — none — —
Losses, the years in between, and dividends:
Shares, outside — A fund or ETF, outside — Inside the account
Losses — offset gains on shares; carry forward (the four-week rule limits a loss on shares bought back within four weeks) — no relief: a fund''s loss cannot be set against anything — the charge is payable in a losing year too
While you hold — nothing — a deemed disposal every eight years: the gain taxed as if sold, credited at the real sale — nothing
Dividends — income (section 5) — taxed at the exit-tax rate — no Irish tax; US withholding — for the Act to settle', 218, '2026-11-12T13:40:44.802Z'),
  ('K-COSTS.6', 'kit/costs-and-tax-walkthrough.md', 'Costs and tax — the walkthrough', '4 · The same gain taxed three ways (2)', 'What it comes to on the worksheet''s gain, when it is paid, and what is law tonight:
Shares, outside — A fund or ETF, outside — Inside the account
On €3,000 — €536.30 (31% of €1,730) — €1,050 (35% of €3,000; €1,140 if sold in 2026) — €0 (the balance never passes €50,000)
When and how — pay by 15 December (disposals Jan–Nov) or 31 January (December''s); return by 31 October of the following year on CG1 or Form 11 / Form 12 — an ETF (held through a clearing system) and an EU fund: self-assessed on Form 11 / Form 12 by 31 October of the following year, for a sale or an eighth anniversary; an Irish non-ETF fund deducts the tax itself — the provider calculates it each 31 December and deducts it by 14 April; you file nothing
Status tonight — the rate is a Bill (announced, drafted, not yet an Act); the exemption and the dates are current law — the 35% is a Bill; the 38% is law — the whole account is a Bill, to open from 1 July 2027 on a commencement order', 190, '2026-11-12T13:40:44.802Z');
INSERT INTO notes (id, source, title, heading, body, words, seeded_at) VALUES
  ('K-COSTS.7', 'kit/costs-and-tax-walkthrough.md', 'Costs and tax — the walkthrough', '4 · The same gain taxed three ways (3)', 'The Individual Investment Account (the Bill''s name; "Personal Investment Account" in the Budget speech): 18 or over, Irish-resident, one account per person; contributions of up to €12,000 a year, no minimum, no lock-in; eligible assets are listed shares and bonds, UCITS funds and ETFs, and insurance products; transfers between providers; providers register with Revenue. Two things the Bill as published does not settle: whether a share listed only in the US qualifies as an eligible asset, and how US withholding is treated inside. Both are for the Act and Revenue''s guidance. A €10,000 start fits one year''s allowance; a €50,000 pot takes at least five years of contributions.', 108, '2026-11-12T13:40:44.802Z'),
  ('K-COSTS.8', 'kit/costs-and-tax-walkthrough.md', 'Costs and tax — the walkthrough', '5 · Dividends', '- A US dividend: 30% withheld at source, 15% with a W-8BEN on file; then income in Ireland — taxed at your marginal rate with USC and PRSI, with credit for the 15%.
- An Irish company''s dividend: 25% dividend withholding tax taken, credited against the income tax due.
- A fund''s distribution: the exit-tax rate (38% in 2026; 35% from 2027 — the Bill), no USC or PRSI on top.
- The worksheet shows the withholding and stops: the rest depends on the person.', 85, '2026-11-12T13:40:44.802Z'),
  ('K-COSTS.9', 'kit/costs-and-tax-walkthrough.md', 'Costs and tax — the walkthrough', '6 · The record you keep', 'For every buy and sell: the date, the quantity, the price, the currency conversion rate, the cost line — and the reason. The broker''s annual statement is raw data (it reports nothing to Revenue for you); the ticket has carried all of this since week 8, and a journal entry is a tax record with a reason attached. Keep contract notes; keep the dividend statements (they show the withholding); keep the eighth anniversaries of any fund in a diary.', 79, '2026-11-12T13:40:44.802Z'),
  ('K-COSTS.10', 'kit/costs-and-tax-walkthrough.md', 'Costs and tax — the walkthrough', '7 · The dates, in one place', 'What — When
CGT on disposals 1 January – 30 November — pay by 15 December of the same year
CGT on disposals in December — pay by 31 January of the following year
The CGT return (CG1 / Form 11 / Form 12) — 31 October of the following year
The exit tax on an ETF sold, or on an eighth anniversary — self-assessed in the return for that year, by 31 October of the following year (an Irish non-ETF fund deducts the tax itself)
The 31% CGT rate — the Bill — disposals on or after 7 October 2026
The 35% exit tax — the Bill — 1 January 2027, as announced
The Individual Investment Account — 1 July 2027, on a commencement order
The Finance (No. 2) Bill 2026 — published 19 October 2026; an Act when passed, usually December', 143, '2026-11-12T13:40:44.802Z'),
  ('K-COSTS.11', 'kit/costs-and-tax-walkthrough.md', 'Costs and tax — the walkthrough', '8 · The discipline', 'Every figure above carries a date. A Bill is not an Act: before anyone acts on a figure marked "the Bill", it is re-checked against the Finance Act and Revenue''s published guidance. The toolkit''s worksheet prints the date it was checked on and marks every line that depends on the Bill; the course updates it when the law changes. That is the habit — not the numbers.
Sources, as read on 12 November 2026: the Budget 2027 statement and main points (6 October 2026); the Finance (No. 2) Bill 2026 as published (19 October 2026) and the professional firms'' summaries of its investment-account, CGT and fund-tax sections; Revenue''s guidance on capital gains tax payment dates and the annual exemption; the broker''s published fee schedule and the Central Bank''s consumer pages on checking a firm. Education, not advice — nothing in this kit is a recommendation to buy or sell anything, to use any broker, or to arrange anyone''s tax.', 159, '2026-11-12T13:40:44.802Z'),
  ('K-SCAMS.1', 'kit/scam-spotting-notes.md', 'Scam-spotting notes', 'Overview', 'Takeaway kit · Intro to the Stock Market · part 1 from lesson 6, part 2 from lesson 11
The course is designed to stop you losing money to bad process, high costs and scams — which, for most people who invest, is where the real money goes. Two pages of habits. None of them needs you to know anything about any company.', 63, '2026-11-12T13:40:44.802Z'),
  ('K-SCAMS.2', 'kit/scam-spotting-notes.md', 'Scam-spotting notes', 'Part 1 — Stories versus numbers (lesson 6) (1)', '1. Every tip is a story. Mr. Market "lets his enthusiasm or his fears run away with him" (Graham, ch. 8), and now he lives in your pocket. The defence is not cynicism but a habit: every sentence about a company should point at a number on the record, and the number should be one you can find yourself.
2. "Guaranteed returns" is the whole tell. A share''s return is not known in advance by anyone; a 12% target is a target for the account''s movement either way (week 8). Anyone who guarantees a number is describing a product that does not exist or one that is not a share.
3. The pump. A story, a chat group, a surge, a crowd of buyers, the insiders out. The course''s rule reads the price (week 7) and sizes on the volatility (week 8); a share that jumped 40% on a story has a volatility the rule will size down, and a forecast capped at ±20 whatever the story says.
4. The finfluencer. A confident voice, a screenshot of a win, no mention of the losses, no number you can check. Ask: where is the record? Which number? Dated when? The course''s explainer (week 6) and tutor (week 10) show their sources on every paragraph — that is the standard, and a human voice should meet it too.', 226, '2026-11-12T13:40:44.802Z'),
  ('K-SCAMS.3', 'kit/scam-spotting-notes.md', 'Scam-spotting notes', 'Part 1 — Stories versus numbers (lesson 6) (2)', '5. The confident wrong answer. The better the prose, the more it is worth checking. A number from nowhere, a claim with no source, a reason that is really a feeling. The toolkit flags these in its own output; the habit is to do the same to everyone''s.
6. Opacity is the signal. The course is built in the open — every rule, every figure, every check — because opacity is where the fee-takers and the scammers live. When you cannot see how a number was made, that is the finding.', 91, '2026-11-12T13:40:44.802Z');
INSERT INTO notes (id, source, title, heading, body, words, seeded_at) VALUES
  ('K-SCAMS.4', 'kit/scam-spotting-notes.md', 'Scam-spotting notes', 'Part 2 — The platform itself (lesson 11) (1)', 'The four checks, before any money moves:
1. The register. An Irish-authorised firm is on the Central Bank of Ireland''s register (registers.centralbank.ie — "Check if a firm is regulated"); a firm serving Ireland from another EU country under the passport is on its home regulator''s register. No register, no broker.
2. The number from the register. A clone firm copies a real firm''s name, address and authorisation number and changes the bank account. The Bank publishes a warning about one most weeks. Call the number the register gives, not the one you were given.
3. The fee page. A real broker publishes one (lesson 11''s walkthrough reads it line by line). A "platform" with no schedule, or a "manager" who takes a share of profits, is a different thing.
4. The exit. How do you get your money out, in what currency, in how many days, at what fee? If the answer is a story, stop.
The red flags, one breath each:
- An unregistered or "offshore-regulated" platform; a licence number you cannot find on a register.
- Guaranteed, "fixed" or "risk-free" returns; a return quoted per month.
- Pressure: a deadline, a bonus for depositing today, a call every day.
- An advert or a celebrity that found you; a message from a stranger; a "tip" in a group.', 220, '2026-11-12T13:40:44.802Z'),
  ('K-SCAMS.5', 'kit/scam-spotting-notes.md', 'Scam-spotting notes', 'Part 2 — The platform itself (lesson 11) (2)', '- Remote-access software "to help you set up"; being asked for your password or your card.
- A dashboard that only ever goes up; profits you can see but not withdraw; a fee to withdraw.
- A second firm that will "recover your losses" for a fee — the same people, a second time.
- Crypto or forex "platforms" with a manager; anything outside the course''s universe of listed shares and funds on a regulated exchange.
What you lose with an unauthorised firm: the Investor Compensation Scheme (90% of a claim up to €20,000 against an authorised Irish firm) and the Financial Services and Pensions Ombudsman — both exist only for authorised firms. With an unauthorised one there is nobody to complain to and nothing to claim from.
Report it: the Central Bank of Ireland, (01) 224 5800; centralbank.ie/financialscams (the warnings list and the reporting form) — both as printed on the Bank''s own warning notices (checked November 2026; the Bank''s site is the source if either changes). Keep the messages, the account names, the dates.
The link to the course: a confident wrong answer and a confident wrong platform sell the same way — fluency. The defence is the same: find the register entry, find the number, check it yourself, write it down.

Education, not advice. Nothing in this kit is a recommendation to use or avoid any particular firm; the habits are the point.', 236, '2026-11-12T13:40:44.802Z');
